(function (root) {
  'use strict';
  var FT = root.CALR_FULLTEXT = root.CALR_FULLTEXT || {};
  FT["PH-H1206"] = {"id":"PH-H1206","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1372_1955.html","fetchedAt":"2026-10-06","articleCount":1,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Adjustment of the Salaries of the Members of the Faculty of the Philippine Normal College in Accordance with the Salary Scale Used by the University of the Philippines","orig":"An Act Providing for the Adjustment of the Salaries of the Members of the Faculty of the Philippine Normal College in Accordance with the Salary Scale Used by the University of the Philippines"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1372","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 1 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1372_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1206-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provisions of law and especially of sections three and four of Commonwealth Act Numbered Four hundred two and the interpretations thereof by the Salary Board and other competent authority to the con­trary notwithstanding, the minimum and maximum rates of annual compensation of the members of the faculty of the Philippine Normal College as hereby classified shall be as follows:\nProfessorial Rank\nEducational Attainment\nSalary range Professor Ph. D., Ed. D.\nP7,320.00—P8,760.00\nM. A., M. Ed 6,960.00—8,400.00 Associate Ph. D., Ed. D.\n5,940.00—6,540.00 Professor\nM. A., M. Ed.\n5,640.00—6,360.00 Assistant Ph. D., Ed. D.\n4,620.00—5,220.00 Professor\nM. A., M. Ed.\n4,320.00—3,840.00 Instructor\nM. A., M. Ed.\n3,240.00—3,840.00"}}],"pack":"ph-p17"};
  FT["PH-H1207"] = {"id":"PH-H1207","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1373_1955.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Authorizing the Philippine Sportswriters Association to Hold One Benefit Boxing Show Every Year, the Net Proceeds of Which Shall Constitute a Trust Fund for the Benefit of Disabled Filipino Boxers","orig":"An Act Authorizing the Philippine Sportswriters Association to Hold One Benefit Boxing Show Every Year, the Net Proceeds of Which Shall Constitute a Trust Fund for the Benefit of Disabled Filipino Boxers"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1373","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1373_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1207-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Philippine Sportswriters Association is authorized to hold one benefit boxing show every year, the net proceeds of which shall be for the benefit of disabled Filipino boxers.\nThe benefit boxing shows promoted by the Philippine Sportswriters Association pursuant to the provisions of this Act shall be exempt from all taxes."}},{"id":"PH-H1207-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The net proceeds of the benefit boxing shows shall constitute a trust fund to be known as the \"Disabled Filipino Boxers Trust Fund\" and shall be administered by a Board of Trustees, composed of the Chairman of the Games and Amusements Board, as chairman, and a representative of the Philippine Sportswriters Association and of the Philippine Boxing Association, as members."}},{"id":"PH-H1207-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Subject to the rules and regulations as the Board of Trustees may from time to time promulgate, the trust fund shall be available for the benefit of poor and deserving disabled Filipino boxers."}},{"id":"PH-H1207-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1208"] = {"id":"PH-H1208","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1374_1955.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Authorizing the Execution of Public Works Projects or Parts Thereof on Piece Work or “Takay” Basis","orig":"An Act Authorizing the Execution of Public Works Projects or Parts Thereof on Piece Work or “Takay” Basis"},"level":"law","status":"active","topics":["culture"],"docNumber":"Republic Act No. 1374","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1374_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1208-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law, executive order, rule or regulation to the contrary notwithstanding, public works engineers may execute public works projects or parts thereof on piece work or \"takay\" basis."}},{"id":"PH-H1208-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Any public works engineer, before executing any public works project or a part thereof on piece work or \"takay\" basis, shall first determine the volume of work which an average laborer can perform in eight hours, and, on the basis of the minimum wage rate prescribed by law, fix the unit measure of work and the payment therefor."}},{"id":"PH-H1208-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Laborers who work on piece work or \"takay\" basis shall be paid through payroll, which shall contain the names of the laborers, the total volume of work performed by each laborer or by a group of laborers in terms of the number of unit measures as fixed in accordance with the preceding section, and the total amount of the payment therefor: Provided, However , That when piece work is undertaken by several laborers as a group, the payment shall be divided equally among them unless they all authorize in writing one among themselves to collect payment on their behalf, which authorization shall be noted on the payroll and attached thereto. The payroll shall also contain a certificate by the public works engineer or his authorized representative in charge of the work that the statements appearing thereon are of his own knowledge true and correct and that no fraud or collusion has been committed in connection with the work covered by such payroll."}},{"id":"PH-H1208-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Public Works and Communications shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H1208-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1209"] = {"id":"PH-H1209","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1375_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Sections One and Two of Republic Act Numbered Six Hundred One, as Amended by Republic Acts Numbered Eleven Hundred Seventy-Five and Eleven Hundred Ninety-Seven","orig":"An Act Amending Sections One and Two of Republic Act Numbered Six Hundred One, as Amended by Republic Acts Numbered Eleven Hundred Seventy-Five and Eleven Hundred Ninety-Seven"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1375","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1375_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1209-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections one and two of Republic Act Numbered Six hundred one, as amended by Republic Acts Numbered Eleven hundred seventy-five and Eleven hundred ninety-seven, are further amended to read as follows:\n\"Sec. 1. Except as herein otherwise provided, there shall be assessed, collected, and paid a special excise tax of seventeen per centum on the value in Philippine peso of foreign exchange sold and/or authorized to be sold by the Central Bank of the Philippines, or any of its agents until June thirtieth, nineteen hundred and fifty-six.\n\"Sec. 2. The tax provided for in section one of this Act shall not be collected on foreign exchange used for the payment of the cost, transportation and/or other charges incident to importation into the Philippines of canned milk, canned beef, cattle, canned fish, cocoa beans, malt, stabilizer and flavors, vitamin concentrate; supplies and equipment purchased directly by the Government or any of its instrumentalities for its own exclusive use; machinery, equipment, accessories, and spare parts, for the use of industries, miners, mining enterprises, planters and farmers; and fertilizers when imported by planters or farmers directly or through their cooperatives; articles or containers used, including materials for the manufacture of tin containers used by the importer himself in the manufacture or preparation of local products for consignment or export abroad; textbooks, reference books, and supplementary readers approved by the Board on Textbooks and/or established public or private educational institutions; paper imported by publishers for their exclusive use in the publication of books, pamphlets, magazines and newspapers; carbides, explosives and dynamite for mining purposes; drugs and medicines, and medical and hospital supplies listed in the appendix of this Act; payment in respect of reinsurance; payment in respect of marine and aviation insurance; spare parts to be used in the repair of vessels of Philippine registry or airplanes and such other parts thereof as may be certified by the Hulls and Boilers Division of the Bureau of Customs or the Civil Aeronautics Administration, respectively, as essential to the maintenance of vessels or airplanes; payment of purchase price of vessels or ships of any kind or nature intended for Philippine registry, ninety per cent of the ownership of which belongs exclusively to Filipinos, or charter fees of airplanes and vessels of Philippine register; remittances by airlines of American registry operating between the Philippines and the United States of income in the Philippines to their head offices in the United States: Provided, That such airlines have been granted a permit to operate under the Air Transport Agreement between the United States and the Philippines prior to the enactment of Republic Act Numbered Six hundred one; remittances for payment of principal and interests of foreign loan contracted under obligation of the Philippine Government or any of its instrumentalities; remittances for payment of living expenses of students pursuing courses of studies abroad not exceeding the equivalent of two hundred and fifty dollars per month including payment of tuition, books, medical expenses and other school fees; and dollar allocations for one trip a year and not exceeding three hundred dollars for each Filipino pilgrim of any religion travelling abroad under permit of the Government; payment of premiums by veterans on life insurance policies under the Government of the United States; and payment of premiums and other amounts due by policy-holders on life insurance policies issued before December nine, nineteen hundred and forty-nine, and payment of machinery and/or raw materials to be used by new and necessary industries as determined in accordance with Republic Act Numbered Thirty-five as amended by Republic Act Numbered Nine hundred and one.\""}},{"id":"PH-H1209-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect on July 1, 1955.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1210"] = {"id":"PH-H1210","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1376_1955.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Two Hundred and Fifty Thousand Pesos for the Establishment and Maintenance of Provincial Soil Offices and Regional Soil Laboratories to Bring the Benefits of Soil Chemical Analysis and Other Related Services to the Farming Population for the Purpose of Increasing Crop Production","orig":"An Act Appropriating Two Hundred and Fifty Thousand Pesos for the Establishment and Maintenance of Provincial Soil Offices and Regional Soil Laboratories to Bring the Benefits of Soil Chemical Analysis and Other Related Services to the Farming Population for the Purpose of Increasing Crop Production"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 1376","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1376_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1210-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of two hundred and fifty thousand pesos is hereby appropriated out of any funds in the National Treasury not otherwise appropriated for the establishment and maintenance of regional soil laboratories and provincial soil offices under the Bureau of Soil Conservation: Provided, That one hundred and thirty thousand pesos shall be used for the construction of buildings and purchase of equipment and chemicals, and the remaining one hundred and twenty thousand pesos for salaries and traveling expenses of personnel."}},{"id":"PH-H1210-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The regional soil laboratories will undertake all soil analysis and research work in the region, while the provincial soil offices will extend cooperative work to the farmers with a view to solving their soil problems. The provincial soil offices will also have custody of the official records, gather data and statistics, and give advice and information to the public regarding soils in the province."}},{"id":"PH-H1210-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1211"] = {"id":"PH-H1211","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1377_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend Section Twenty of Commonwealth Act Numbered One Hundred Eighty-Six, as Amended by Republic Act Numbered Six Hundred Sixty, Entitled “An Act to Create and Establish a ‘Government Service Insurance System’ to Provide for its Administration and to Appropriate the Necessary Funds Therefor”","orig":"An Act to Amend Section Twenty of Commonwealth Act Numbered One Hundred Eighty-Six, as Amended by Republic Act Numbered Six Hundred Sixty, Entitled “An Act to Create and Establish a ‘Government Service Insurance System’ to Provide for its Administration and to Appropriate the Necessary Funds Therefor”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1377","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1377_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1211-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section twenty of Commonwealth Act Numbered One hundred eighty-six, as amended by Republic Act Numbered Six hundred sixty, is hereby amended to read as follows:\n\"Sec. 20. Auditing and legal service. — The Auditor General and the Secretary of Justice shall be the ex-officio Auditor and Legal Adviser of the System, respectively. The Auditor General, or his authorized representative, shall submit to the Board soon after the close of each fiscal year audited statements showing the financial condition and progress of the System for the fiscal year just closed, and the Actuary shall make, as of the end of each fiscal year, an actuarial examination and valuation of the System: Provided, However , That the Insurance Commissioner or his authorized representatives shall make an examination into the financial condition and methods of transacting business of the system at least once in two years and the report of said examination shall be submitted to the board and copies thereof be furnished the Congress and the Office of the President of the Philippines within a reasonable time after the close of the examination: And Provided, finally, That for each examination the system shall apply to the Office of the Insurance Commissioner an amount equal to the actual expenses of said office in the conduct of the examination, including the salaries of the examiners and of the actuary of said office who have been assigned to make such examination for the actual time spent in said examination.\""}},{"id":"PH-H1211-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1212"] = {"id":"PH-H1212","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1378_1955.html","fetchedAt":"2026-10-06","articleCount":23,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Regulate the Trade of Master Plumber","orig":"An Act to Regulate the Trade of Master Plumber"},"level":"law","status":"active","topics":["trade"],"docNumber":"Republic Act No. 1378","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 23 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1378_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 24 条，缺 2）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1212-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act shall be known as the \"Plumbing Law.\"\nSection 2. (a) The practice of plumbing within the meaning and intent of this Act shall embrace services in the form of consultations, designing, preparation of plans, specifications, estimates, erection, installation and supervision of plumbing work including the inspection and acceptance of materials used therein extension and alteration of all pipings to fixtures, appliances, and appurtenances in connection with any of the following: storm and sanitary drainage, facilities of buildings, the sanitary venting of fixtures, hot or cold water supply systems within or adjacent to any building, storm drains, sewerage system of any premises and/or connection with any public disposal or any acceptable terminal. The enumeration in this paragraph shall not be construed as excluding any other work requiring plumbing knowledge and application.\n(b) The term \"master plumber\" as used in this Act shall mean a person duly registered with the Board of Examiners for Master Plumbers in the manner as hereinafter provided."}},{"id":"PH-H1212-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Within thirty days after the approval of this Act, there shall be created a Board of Examiners for Master Plumbers, hereinafter referred to as the Board, to be composed of a Chairman and two members who shall be appointed by the President of the Philippines upon the recommendation of the Commissioner of Civil Service in consultation with a duly registered national association of master plumbers. The members of the Board shall hold office for a term of three years. The first members of the Board appointed under this Act shall hold office for the following terms: One member for one year; one member for two years; and one member for three years. Each member of the Board shall qualify by taking the proper oath of office before entering upon the performance of his duties. Any member of the Board may be removed by the President of the Philippines for neglect of duty, incompetency, malpractice, and unprofessional, unethical, immoral, or dishonorable conduct, after said member has been given opportunity to defend himself in an administrative investigation duly held. Vacancies in the Board shall be filled for the unexpired term."}},{"id":"PH-H1212-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Board shall administer the provisions of this Act; issue, suspend or revoke certificates of registration of master plumbers; and administer oaths in connection with such certificates of registration.\nIn carrying into effect the provisions of this Act, the Board may, under the hand of its chairman and the seal of the Board, issue subpoena and subpoena duces tecum, to compel the attendance of witnesses and require the production of books, documents, and similar evidence in a case involving violation of any of the provisions of this Act. Any member of the Board may administer oaths or affirmations to witnesses appearing before it.\nIf any person shall refuse to obey any subpoena or subpoena duces tecum so issued, or shall refuse to testify or produce any book, record, or document, the Board may present its petition to the Court of First Instance, setting forth the facts, and thereupon such court shall, in a proper case, issue its subpoena to such person, requiring his appearance before such court and there to testify or produce such books, records or documents, as may be deemed necessary and pertinent by the Board. Any person failing or refusing to obey the subpoena or subpoena duces tecum or order of the said court may be proceeded against in the same manner as for refusal to obey any other subpoena or subpoena duces tecum or order of the court.\nThe Board shall, from time to time, look into conditions affecting the trade of master plumber in the Philippines, and whenever necessary, recommend to the President of the Philippines the adoption of such rules and regulations as may be deemed proper for the maintenance of good ethics and standards in the trade and for the protection of public welfare, life, health, and property."}},{"id":"PH-H1212-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The President of the Philippines is hereby authorized to issue rules and regulations to carry into effect the objectives of this Act, upon recommendation of the Board of Examiners for Master Plumbers and in consultation with a duly registered national association of master plumbers, in accordance with the following basic principles, except in cases where it may prove oppressive or excessively burdensome to those without sufficient means and to such buildings, structures or constructions valued at five thousand pesos or less:\n(a) All premises intended for human habitation, occupancy, or use shall be provided with a supply of pure and wholesome water, neither connected with unsafe water supplies nor subject to the hazards of backflow or backsiphonage.\n(b) Plumbing fixtures, devices, and appurtenances shall be supplied with water in sufficient volume and at pressures adequate to enable them to function satisfactorily and without undue noise under all normal conditions of use.\n(c) Plumbing shall designed and adjusted to use the minimum quantity of water consistent with proper performance and cleaning.\n(d) Devices for heating and storing water shall be so designed and installed as to prevent dangers from explosion through overheating.\n(e) Every building having plumbing fixtures installed and intended for human habitation, occupancy, or use on premises abutting on a street, alley, or easement in which there is a public sewer shall have a connection with the sewer.\n(f) Each family dwelling unit on premises abutting on sewer or with a private sewage-disposal system shall have, at least, one water closet and one kitchen-type sink. It is further recommended that a lavatory and bath-tub or shower shall be installed to meet the basic requirements of sanitation and personal hygiene.\nAll other structures for human occupancy or use on premises abutting on a sewer or with a private sewage-disposal system shall have adequate sanitary facilities but in no case less than one water closet and one other fixture for cleansing purposes.\n(g) Plumbing fixtures shall be made of smooth non-absorbent material, and shall be free from concealed fouling surface.\n(h) The drainage system shall be designed, constructed, and maintained so as to guard against fouling, deposit of solids, and clogging, and with adequate cleanouts so arranged that the pipes may be readily cleaned.\n(i) The piping of the plumbing system shall be of durable materials, free from defective workmanship and so designed and constructed as to give satisfactory service for its reasonable expected life.\n(j) Each fixture directly connected to the drainage system shall be equipped with a water-seal trap.\n(k) The drainage system shall be designed to provide an adequate circulation of air in pipes with no danger of siphonage, aspiration, or forcing of trap seals under condition of ordinary use.\n(l) Each terminal shall extend to the outer air and be so installed as to minimize the possibilities of clogging and the return of foul air to the building.\n(m) The plumbing system shall be subject to such tests as will effectively disclose all leaks and defects in the work.\n(n) No substance which will clog the pipes, produce explosive mixtures, destroy the pipes or their joints, or interfere unduly with the sewage-disposal process shall be allowed to enter the building drainage system.\n(o) Proper protection shall be provided to prevent contamination of food, water, sterile goods, and similar materials by backflow of sewage. When necessary, the fixture, device, or appliance shall be connected indirectly with the building drainage system.(p) No water closet nor urinal shall be located in a room or compartment which is not properly lighted and ventilated.\n(q) If water closets or other plumbing fixtures are installed in buildings where there is no sewer within a reasonable distance, suitable provision shall be made for disposing of the building sewage by some accepted method of sewage treatment and disposal.\n(r) Where a plumbing drainage system may be subjected to backflow of sewage, suitable provision shall be made to prevent its overflow in the building.\n(s) Plumbing system shall be maintained in a sanitary and serviceable condition.\n(t) All plumbing fixtures shall be so installed with regard to spacing as to be reasonably accessible for their intended use.\n(u) Plumbing shall be installed with due regard to preservation of the strength of structural members and prevention of damage to walls and other surfaces through fixture usage.\n(v) Sewage or other waste from a plumbing system which may be deleterious to surface or subsurface waters shall not be discharged into the ground or into any water-way unless it has first been rendered innocuous through subjection to some acceptable form of treatment."}},{"id":"PH-H1212-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Each member of the Board shall, at the time of his appointment:\n(a) Be a citizen and resident of the Philippines;\n(b) Be at least thirty years of age and of good moral character; and\n(c) Has been actively engaged in the trade of master plumber for at least five years."}},{"id":"PH-H1212-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The Board of Examiners shall charge for each applicant for examination, the sum of thirty-five pesos, and for each certificate of registration, ten pesos."}},{"id":"PH-H1212-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The members of the Board shall each receive as compensation, the sum of ten pesos for each applicant examined. All authorized expenses of the Board shall be paid by the Bureau of Civil Service. All fees shall be received by the disbursing officer of the Bureau of Civil Service, and said officer shall pay all authorized expenses of the Board, including the compensation provided hereinabove for members of the Board."}},{"id":"PH-H1212-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The Commissioner of Civil Service shall be the executive officer of the Board, and shall conduct the examinations given by the Board and shall designate any subordinate officer of the Bureau of Civil Service to act as secretary of the Board. All records and minutes of the Board, including all examination papers, shall be kept by the Bureau of Civil Service."}},{"id":"PH-H1212-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The Board shall submit an annual report to the President of the Philippines after the close of each fiscal year, giving a detailed account of its proceedings during the year and making such recommendation as may be deemed proper."}},{"id":"PH-H1212-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"A roster showing the names and addresses of master plumbers shall be prepared by the Commissioner of Civil Service during the month of July of every year. Copies of this roster shall be mailed to each person so registered placed on file with the Office of the President of the Philippines; and copies thereof shall be furnished to all Department Heads, to the mayors of all chartered cities, to the Director of Health, Director of Public Works, District Engineers, City Engineers, and to such other bureaus, government agencies and provincial and municipal authorities as may be deemed necessary, and to the public, upon request."}},{"id":"PH-H1212-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"All applicants for registration as master plumber shall be required to pass an examination as hereinafter provided.\nPersons applying for admission to the examination as herein provided, shall, prior to the date of the examination, establish to the satisfaction of the Board of Examiners, that he:\n(a) Is at least twenty-one years of age;\n(b) Is a citizen of the Philippines;\n(c) Is of good moral character;\n(d) Is at least a high school graduate;\n(e) Has at least five years experience in actual plumbing work under the supervision of a registered master plumber."}},{"id":"PH-H1212-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Applicants for registration as master plumbers shall be examined in the following subjects:\n(a) Plumbing arithmetic, ten per cent;\n(b) Plumbing Code, ten per cent;\n(c) Sanitation, plumbing design and installation, forty per cent;\n(d) Practical problems, twenty per cent;\n(e) Oral practical problems and experience, twenty per cent."}},{"id":"PH-H1212-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The Board shall, within one hundred and twenty days after the date of completion of the examination, report the rating obtained by each candidate to the Commissioner of Civil Service, who shall submit such ratings to the President of the Philippines."}},{"id":"PH-H1212-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The Office of the President, upon the recommendation of the Board, shall issue a certificate of registration upon payment of the registration fee as provided in this Act to any applicant, who has satisfactorily met all the requirements specified in this Act.\nAll certificates of registration shall show the full name of the registrant, shall have a serial number, and shall be signed by all members of the Board, the President of the Philippines and the Commissioner of Civil Service, and shall bear the official seal of the Board.\nThe issuance of a certificate of registration by the Board to a registrant shall be evidence that the person named therein is entitled to all the rights and privileges of a registered master plumber, while said certificate remains unrevoked."}},{"id":"PH-H1212-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"All successful candidates shall be required to take an oath before the Board or any other Government official authorized to administer oaths, prior to engaging in the trade of registered master plumber."}},{"id":"PH-H1212-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Examination and registration shall not be required of the following persons:\n(a) Officers or enlisted men of the Armed Forces of the United States and of the Philippines and civilian employees of the Government of the United States stationed for the United States and/or the Philippines.\n(b) Plumbing experts called in by the Philippine Government for consultation in connection with certain specific construction, provided that their services shall be limited to such work."}},{"id":"PH-H1212-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"The Board shall not issue a certificate to any person convicted by a court of competent jurisdiction for any criminal offense involving moral turpitude, or to any person found guilty of immoral or dishonorable conduct, or to any person of unsound mind. In the event of a refusal to issue a certificate to any person, the Board shall give to the applicant a written statement setting forth its reason for such action, which statement shall be incorporated into the records of the Board."}},{"id":"PH-H1212-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Subject to the approval of the President of the Philippines, the Board shall have the power, after due notice and hearing, to suspend or revoke the certificate of registration for any of the causes mentioned in the preceding section. The Board may, upon application and upon satisfactory showing, reinstate a registered master plumber whose certificate of registration has been suspended or revoked."}},{"id":"PH-H1212-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Any person who shall engage in plumbing in the Philippines without being registered in accordance with the provisions of this Act, or any person presenting or attempting to use as his own the certificate of registration of a registered master plumber, or any person who shall give any false or forged evidence of any kind to the Board, or any person who shall impersonate any registered master plumber, or any person who shall attempt to use a revoked or suspended certificate of registration, or any person who shall use in connection with his name or otherwise assume, use, or advertise any title or description tending to convey the impression that he is a registered master plumber, or any person who shall violate any of the provisions of this Act shall be guilty of a misdemeanor and shall, upon conviction, be sentenced to a fine of not less than five hundred pesos nor more than two thousand pesos, or to suffer imprisonment for a period of not less than six months nor more than one year, or both, in the discretion of the court."}},{"id":"PH-H1212-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"No person who is not a citizen of the Philippines at the time he applies for examination shall be allowed to take it unless he can prove in the manner provided by law that, the country or state of which he is a citizen, subject, or national, either admits citizens of the Philippines to engage in the same trade without restriction or allows them to practice it after an examination on terms of strict and absolute equality with citizens, subjects, or nationals of the country concerned, including the unconditional recognition of degrees issued by institutions of learning duly recognized for the purpose by the Government of the Philippines."}},{"id":"PH-H1212-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"As soon as this Act shall take effect, any person desiring to practice the trade of master plumber, shall be required to obtain a certificate of registration in the manner and under the conditions herein provided.\nAll master plumbers duly registered and examined under the provisions of city ordinances in force one year prior to the effectivity of this Act and all persons with at least five years of continuous practice as plumbers and certified to as capable to practice the trade by the Board of Examiners within one year after the effectivity of this Act, shall be automatically registered under the provisions hereof. Certificates of registration held by such persons in good standing shall have the same force and effect as though the same had been issued under the provisions of this Act."}},{"id":"PH-H1212-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"The provisions of this Act shall apply only in chartered cities."}},{"id":"PH-H1212-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1213"] = {"id":"PH-H1213","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1379_1955.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring Forfeiture in Favor of the State Any Property Found to Have Been Unlawfully Acquired by Any Public Officer or Employee and Providing for the Proceedings Therefor","orig":"An Act Declaring Forfeiture in Favor of the State Any Property Found to Have Been Unlawfully Acquired by Any Public Officer or Employee and Providing for the Proceedings Therefor"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 1379","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1379_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1213-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Definitions. (a) For the purposes of this Act, a \"public officer or employee\" means any person holding any public office or employment by virtue of an appointment, election or contract, and any person holding any office or employment, by appointment or contract, in any State owned or controlled corporation or enterprise.\n(b) \"Other legitimately acquired property\" means any real or personal property, money or securities which the respondent has at any time acquired by inheritance and the income thereof, or by gift inter vivos before his becoming a public officer or employee, or any property (or income thereof) already pertaining to him when he qualified for public office or employment, or the fruits and income of the exclusive property of the respondent's spouse. It shall not include:\n1. Property unlawfully acquired by the respondent, but its ownership is concealed by its being recorded in the name of, or held by, the respondent's spouse, ascendants, descendants, relatives, or any other person.\n2. Property unlawfully acquired by the respondent, but transferred by him to another person or persons on or after the effectivity of this Act.\n3. Property donated to the respondent during his incumbency, unless he can prove to the satisfaction of the court that the donation is lawful."}},{"id":"PH-H1213-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Filing of petition. Whenever any public officer or employee has acquired during his incumbency an amount of property which is manifestly out of proportion to his salary as such public officer or employee and to his other lawful income and the income from legitimately acquired property, said property shall be presumed prima facie to have been unlawfully acquired. The Solicitor General, upon complaint by any taxpayer to the city or provincial fiscal who shall conduct a previous inquiry similar to preliminary investigations in criminal cases and shall certify to the Solicitor General that there is reasonable ground to believe that there has been committed a violation of this Act and the respondent is probably guilty thereof, shall file, in the name and on behalf of the Republic of the Philippines, in the Court of First Instance of the city or province where said public officer or employee resides or holds office, a petition for a writ commanding said officer or employee to show cause why the property aforesaid, or any part thereof, should not be declared property of the State: Provided , That no such petition shall be filed within one year before any general election or within three months before any special election.\nThe resignation, dismissal or separation of the officer or employee from his office or employment in the Government or in the Government-owned or controlled corporation shall not be a bar to the filing of the petition: Provided, however , That the right to file such petition shall prescribe after four years from the date of the resignation, dismissal or separation or expiration of the term of the office or employee concerned, except as to those who have ceased to hold office within ten years prior to the approval of this Act, in which case the proceedings shall prescribe after four years from the approval hereof."}},{"id":"PH-H1213-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The petition. The petition shall contain the following information:\n(a) The name and address of the respondent.\n(b) The public officer or employment he holds and such other public offices or employment which he has previously held.\n(c) The approximate amount of property he has acquired during his incumbency in his past and present offices and employments.\n(d) A description of said property, or such thereof as has been identified by the Solicitor General.\n(e) The total amount of his government salary and other proper earnings and incomes from legitimately acquired property, and\n(f) Such other information as may enable the court to determine whether or not the respondent has unlawfully acquired property during his incumbency."}},{"id":"PH-H1213-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Period for the answer. The respondent shall have a period of fifteen days within which to present his answer."}},{"id":"PH-H1213-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Hearing. The Court shall set a date for a hearing, which may be open to the public, and during which the respondent shall be given ample opportunity to explain, to the satisfaction of the court, how he has acquired the property in question."}},{"id":"PH-H1213-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Judgment. If the respondent is unable to show to the satisfaction of the court that he has lawfully acquired the property in question, then the court shall declare such property, forfeited in favor of the State, and by virtue of such judgment the property aforesaid shall become property of the State: Provided , That no judgment shall be rendered within six months before any general election or within three months before any special election. The Court may, in addition, refer this case to the corresponding Executive Department for administrative or criminal action, or both."}},{"id":"PH-H1213-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Appeal. The parties may appeal from the judgment of the Court of First Instance as provided in the Rules of Court for appeals in civil cases."}},{"id":"PH-H1213-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Protection against self-incrimination. Neither the respondent nor any other person shall be excused from attending and testifying or from producing books, papers, correspondence, memoranda and other records on the ground that the testimony or evidence, documentary or otherwise, required of him may tend to incriminate him or subject him to prosecution; but no individual shall be prosecuted criminally for or on account of any transaction, matter or thing concerning which he is compelled, after having claimed his privilege against self-incrimination, to testify or produce evidence, documentary or otherwise, except that such individual so testifying shall not be exempt from prosecution and conviction for perjury or false testimony committed in so testifying or from administrative proceedings."}},{"id":"PH-H1213-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Immunity. The Solicitor General may grant immunity from criminal prosecution to any person who testifies to the unlawful manner in which the respondent has acquired any of the property in question in cases where such testimony is necessary to prove violations of this Act."}},{"id":"PH-H1213-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Effect of record of title. The fact that any real property has been recorded in the Registry of Property or office of the Register of Deeds in the name of the respondent or of any person mentioned in paragraphs (1) and (2) of subsection (b) of section one hereof shall not prevent the rendering of the judgment referred to in section six of this Act."}},{"id":"PH-H1213-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Laws on prescription. The laws concerning acquisitive prescription and limitation of actions cannot be invoked by, nor shall they benefit the respondent, in respect of any property unlawfully acquired by him."}},{"id":"PH-H1213-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Penalties. Any public officer or employee who shall, after the effective date of this Act, transfer or convey any unlawfully acquired property shall be repressed with imprisonment for a term not exceeding five years, or a fine not exceeding ten thousand pesos, or both such imprisonment and fine. The same repression shall be imposed upon any person who shall knowingly accept such transfer or conveyance."}},{"id":"PH-H1213-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability of provisions. If any provision of this Act or the application thereof to any person or circumstance, is held invalid, the remainder of the Act and the application of such provision to other persons or circumstances shall not be affected thereby."}},{"id":"PH-H1213-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Effective date. This Act shall take effect on its approval, and shall apply not only to property thereafter unlawfully acquired but also to property unlawfully acquired before the effective date of this Act.\nApproved: June 18, 1955"}}],"pack":"ph-p17"};
  FT["PH-H1214"] = {"id":"PH-H1214","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1380_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Further Amend Subparagraph (e) of Section Nine of Republic Act Numbered Three Hundred and Forty, as Amended, so as to Include Service Rendered in the American Red Cross or Philippine Red Cross for Purposes of Retirement","orig":"An Act to Further Amend Subparagraph (e) of Section Nine of Republic Act Numbered Three Hundred and Forty, as Amended, so as to Include Service Rendered in the American Red Cross or Philippine Red Cross for Purposes of Retirement"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1380","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1380_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1214-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subparagraph (e) of section nine of Republic Act Numbered Three hundred and forty, as amended by Republic Act Numbered Eight hundred and sixty-one, is further amended to read as follows:\n(e) Service rendered by him as civilian official or employee in the Government or in the American Red Cross, prior to the creation of Philippine Red Cross, or in the Philippine Red Cross: Provided, That he has rendered at least ten years of active service in the Armed Forces of the Philippines: Provided, further, That if the period of his service as such civilian official or employee is longer than the period of his military service, his services as civilian official or employee shall be credited only as equal to his military service."}},{"id":"PH-H1214-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1215"] = {"id":"PH-H1215","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1381_1955.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Odiongan市","en":"An Act Converting the Odiongan High School in the Municipality of Odiongan, Province of Romblon, into a National Agricultural School Which Shall be Known as the Odiongan National Agricultural School","orig":"An Act Converting the Odiongan High School in the Municipality of Odiongan, Province of Romblon, into a National Agricultural School Which Shall be Known as the Odiongan National Agricultural School"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 1381","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1381_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1215-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Odiongan High School in the Municipality of Odiongan, Province of Romblon, is hereby converted into a national agricultural school which shall be known as the Odiongan National Agricultural School. The said school shall be under the supervision of the Bureau of Public Schools."}},{"id":"PH-H1215-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of three hundred thousand pesos is authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the expenses of the said school during the fiscal year ending June thirty, nineteen hundred and fifty-six, including the purchase or expropriation of additional land for the use of the said school, and of equipment and supplies. Thereafter, the necessary sum of its operation and maintenance shall be included in the annual General Appropriation Acts."}},{"id":"PH-H1215-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1216"] = {"id":"PH-H1216","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1382_1955.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting Reserve Officers with at Least Ten Years of Active Accumulated Commissioned Service Security from Reversion","orig":"An Act Granting Reserve Officers with at Least Ten Years of Active Accumulated Commissioned Service Security from Reversion"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1382","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1382_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1216-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Reserve Officers with at least ten years of active accumulated commissioned service who are still on active duty at the time of the approval of this Act shall not be reverted into inactive status except for cause after proper court martial proceedings or upon their own request: Provided , That for purposes of computing the length of service, six months or more of active service shall be considered one year."}},{"id":"PH-H1216-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Acts, executive orders and regulations issued pursuant to existing law or any part thereof inconsistent with this Act are hereby repealed."}},{"id":"PH-H1216-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1217"] = {"id":"PH-H1217","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1383_1955.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating a Public Corporation to be Known as the National Waterworks and Sewerage Authority","orig":"An Act Creating a Public Corporation to be Known as the National Waterworks and Sewerage Authority"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1383","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1383_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1217-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Creation of the National Waterworks and Sewerage Authority; its general purposes; zone and extent of jurisdiction comprised by it; domicile and place of business of the corporation. For the purpose of consolidating and centralizing all waterworks, sewerage and drainage systems in the Philippines under one control, direction and general supervision, there is hereby created a public corporation to be known as the National Waterworks and Sewerage Authority, which shall be organized within one month after the approval of this Act.\nThe National Waterworks and Sewerage Authority shall own and/or have jurisdiction, supervision and control over all territory now embraced by the Metropolitan Water District as well as all areas now served by existing government-owned waterworks and sewerage and drainage systems within the boundaries of cities, municipalities, and municipal districts in the Philippines, including those served by the Waterworks and Wells and Drills Sections of the Bureau of Public Works: Provided , That the Board of Directors of the National Waterworks and Sewerage Authority, in the interest of the public service, may from time to time extends its territory by the admission or inclusion of any areas served by such works located in any other city, municipality or municipal district in the Philippines.\nThe jurisdiction of the National Waterworks and Sewerage Authority shall extend to the construction, maintenance, operation and control of non-self-supporting and/or non-revenue producing water systems and sanitary works, whether undertaken at the expense of the Authority or through subsidy of the National Government as provided in section ten of this Act.\nThe domicile and place of business of the Authority shall be in the City of Manila."}},{"id":"PH-H1217-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Powers and general functions of the Authority. The powers, functions, and activities of the National Waterworks and Sewerage Authority shall be the following:\n(a) To have continuous succession under its corporate name until otherwise provided by law;\n(b) To prescribe its by-laws;\n(c) To adopt and use a seal and alter it at its pleasure;\n(d) To sue and be sued in any court;\n(e) To construct, maintain, and operate mains, pipes, water reservoirs, machinery, and other waterworks for the purpose of supplying water to the inhabitants of its zone, both for domestic and other purposes; to purify the source of supply, regulate the control and use, and prevent the waste of water; and to fix water rates and provided for the collection of rents therefor;\n(f) To construct, maintain, and operate such systems of sanitary sewers as may be necessary for the proper sanitation of the cities and towns comprising the Authority, and to charge and collect such sums for construction and rates for this service as may be determined by the Board to be equitable and just;\n(g) To construct, maintain and operate such storm drains, artesian wells and springs as may be needed and requested by any city or municipality, and to take control of and administer all such storm drains artesian wells and springs as may now be in actual operation, the respective city, municipality or municipal district concerned to appropriate sufficient funds for the purpose;\n(h) To acquire, purchase, hold, transfer, sell, lease, rent, mortgage, encumber, and otherwise dispose of real and personal property, including rights and franchises, within the Philippines, as authorized by the purposes for which the Authority was created and reasonably and necessarily required for the transaction of the lawful business of the same, unless otherwise provided in this Act;\n(i) To construct works across, or otherwise, any stream, watercourse, canal, ditch, flume, street, avenue, highway, or railway, as the location of said works may require, Provided , That such works be constructed in such manner as to afford security for life and property: And, Provided , further , That the stream, watercourse, canal, ditch, flume, street, avenue, highway, or railway so crossed or intersected be restored to their former state as near as may be, or in a manner not to impair unnecessarily their usefulness. Every person or entity whose right of way is crossed or intersected by said works shall not obstruct the forming of such crossing or intersection and shall grant the Authority the proper authority, upon payment of just compensation, for the execution of such work. The Authority is hereby given the right of way to locate, construct, and maintain such works over and through any of the lands which are now or may be the property of the Government of the Republic of the Philippines or any of its branches and political sub-divisions;\n(j) To exercise the right of eminent domain for the purpose for which the Authority was created, in the manner provided by law for condemnation proceedings by the national, provincial, and municipal governments;\n(k) To issue such regulations as may be necessary for the sanitary protection of watersheds, reservoirs, water mains, springs, and other water sources for the proper operation of sanitary sewers, and for the protection of the water and sewer service, as soon as established, any violation of which shall be punished by a fine of not more than five hundred pesos or by imprisonment for not more than six months, or both such fine and imprisonment in the discretion of the court;\n(l) When essential to the proper administration of its corporate affairs or when necessary for the proper transaction of its business or for carrying out the purposes for which it was organized, to contract indebtedness and issue bonds, subject to the approval of the Secretary of Finance. The bonded indebtedness of the Authority, of all classes, shall not at any time exceed one hundred fifty million pesos, and the issue thereof shall be subject to the conditions set forth in section five of this Act; and\n(m) To transact the business for which it was organized and exercise such powers and do such things as may be reasonably necessary to carry out the purposes for which it was established."}},{"id":"PH-H1217-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Board of Directors; its members, reports to the President and Congress of the Philippines. Unless otherwise provided by law, all corporate powers of the National Waterworks and Sewerage Authority shall be exercised, its business managed, and its properties kept and preserved, by a Board of Directors to be composed of five members: a chairman, three other members, and the general manager of the Authority who will be an ex officio member. Two of them must possess knowledge of waterworks, public works and/or sanitary engineering one, knowledge of public health; and one, knowledge of business management and finance. The chairman and the three other members of the Board shall be appointed for a term of six years by the President of the Philippines with the consent of the Commission on Appointments.\nThe Board shall render annual reports to the President and the Congress of the Philippines."}},{"id":"PH-H1217-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"First meeting of the Board; quorum; votes necessary, in general, for adopting resolutions; appeal; per diems of the members; secretary of the Board and his salary. The chairman of the Board shall immediately after the formation thereof, fix a time and place for the first meeting, at which the Board shall adopt rules of procedure and fix a time and place for holding regular meetings.\nNot less than three members of the Board shall constitute a quorum for the transaction of business, and two affirmative votes shall be necessary for the adoption of any resolution or motion, except as herein otherwise provided.\nFor actual attendance at meetings, the chairman of the Board shall receive a per diem of thirty pesos, and each member of the Board of Directors, except the general manager of the Authority, shall receive a per diem of twenty-five pesos.\nThe Board shall appoint its secretary and fix his salary."}},{"id":"PH-H1217-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Resolution to incur indebtedness and issue bonds; their conditions, privileges, and exemptions; sinking funds; guaranty. Whenever the Board may deem it necessary for the Authority to incur indebtedness or issue bonds, it shall by resolution so declare and state the purpose for which the proposed debt is to be incurred and the conditions of the bonds. In order that such resolution be valid, it shall be passed by the affirmative vote of at least three members of the Board and approved by the Secretary of Finance.\nThe bonds shall not be sold at less than par; shall be redeemable at the pleasure of the Board after ten years from date of issue, and payable forty years after date of issue; shall bear interest at an annual rate as determined by the Secretary of Finance; and shall be in registered form and transferable at the office of the National Treasurer. The said bonds are hereby declared exempt from taxation by the Government of the Republic of the Philippines, or by any authority, branch, division or political subdivision thereof, which fact shall be stated upon the face of said bonds. The bonds shall be receivable as security in any transaction with the Government of the Republic of the Philippines in which such security is required.\nA sinking fund shall be created for the payment of the bonds issued under the provisions of this Act in such a manner that the total amount thereof on each annual due date of the bonds issued shall be equal to the total of annuity of such a sum for each million pesos of the bonds outstanding that, together with interest at a rate to be determined by the Secretary of Finance, shall be sufficient to retire the bonds at maturity. The sinking fund shall be under the custody of the Central Bank of the Philippines, which shall invest the same in such manner as the Monetary Board and the Secretary of Finance may approve in accordance with Act Numbered Three thousand fourteen, and shall credit to the same the interest on investment and other incomes accruing to it.\nThe Government of the Republic of the Philippines hereby guarantees the payment by the National Waterworks and Sewerage Authority of both the principal and the interest of the bonds issued by said Authority by virtue of this Act, and shall pay such principal and interest in case the said Authority fails to do so, and there are hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, the sums necessary to make the payments guaranteed by this Act: Provided , That the sums so paid by the Government of the Republic of the Philippines shall be refunded by the National Waterworks and Sewerage Authority, and if said Authority fails to refund the same within thirty days after such payment has been made by the Government of the Republic of the Philippines, the National Treasurer is hereby authorized and directed to retain out of the revenues of the City of Manila and the cities, municipalities and municipal districts included in the Authority, that may come into his possession as belonging to said cities, municipalities and municipal district, the sums necessary to refund the payments made by the Government of the Republic of the Philippines in any proportion which the Auditor General may approve and which will insure their collection."}},{"id":"PH-H1217-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Conduct of affairs and current business; officers and employees of the Authority. The affairs and current business of the National Waterworks and Sewerage Authority shall be conducted under the direction of the Board, by a general manager, an assistant general manager, a chief engineer, an auditor, a treasurer, and such additional officers and employees as the Board may provide.\nThe duties and powers as well as the compensation of said officers and employees shall be such as may be defined and prescribed or fixed by the Board which shall not be inconsistent with the provisions of this Act and other existing laws.\nThe general manager, assistant general manager, chief engineer and treasurer shall be appointed by the President of the Philippines with the consent of the Commission on Appointments, and may be removed for cause by the President of the Philippines.\nAll other officers and employees of the Authority shall be subject to the Civil Service Law, rules and regulations, except those whose positions may, upon recommendation of the Board of Directors, be declared by the President of the Philippines as policy-determining, primarily confidential, or highly technical in nature.\nThe Auditor shall be appointed by the Auditor General with the approval of the President of the Philippines, and may be removed for cause in like manner."}},{"id":"PH-H1217-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"General Manager, Assistant General Manager, Chief Engineer, Treasurer, and Auditor of the Authority; their functions; salaries. The general manager, assistant general manager, chief engineer, treasurer and auditor of the National Waterworks and Sewerage Authority shall each receive an annual salary which shall be fixed by the Board with the approval of the Secretary of Finance. The general manager shall represent the Authority in all its business matters; shall submit to the Board an annual report and such partial reports as he may be required by it or he may see fit to render from time to time, regarding the condition of the business, or of any part of the business of the National Waterworks and Sewerage Authority; and shall perform such other executive duties as may be prescribed by law or may be required of him by resolution of the Board. The assistant general manager shall perform such duties as may be required of him by the Board or the general manager. He shall act as general manager in case of the temporary absence or disability of the general manager. The chief engineer and treasurer shall perform such duties as may be required of them by the Board or the general manager.\nThe Auditor shall be the representative of the Auditor General who is hereby designated ex officio auditor of the National Waterworks and Sewerage Authority.\nThe Auditor shall be the chief of its auditing and accounting department. He shall audit, examine and settle all accounts of the National Waterworks and Sewerage Authority according to existing law and regulations, and shall perform such other duties as the Auditor General, the General Manager or the Board may require of him from time to time. The employees of the Auditor's office shall be appointed by the Auditor General, who, with the approval of the Board, shall fix the number and salaries of the said employees."}},{"id":"PH-H1217-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Dissolution of the Metropolitan Water District; transfer to the Authority of its records, assets and liabilities; transfer to the Authority of entities, waterworks and sewerage systems in the cities, municipalities, municipal districts, and other government waterworks, and sewerage systems. The present Metropolitan Water District created under Act Numbered Two thousand eight hundred thirty-two, as amended, is hereby dissolved and its records, assets and liabilities are transferred to the Authority. All existing government-owned waterworks and sewerage systems in the cities, municipalities, and municipal districts, including springs and other water sources, as well as the waterworks and sewerage bonds, sinking funds, and all indebtedness in general of the said Metropolitan Water District, and government-owned waterworks and sewerage systems, are transferred to the National Waterworks and Sewerage Authority, and the Board is hereby authorized and directed to receive and assume all such assets and liabilities on behalf of the said Authority and in turn to pledge such assets as security for the payment of the waterworks and sewerage bonded debt.\nThe net book value of the properties and assets of the Metropolitan Water District and of government-owned waterworks and sewerage systems in cities, municipalities, or municipal districts, and other government-owned waterworks and sewerage systems shall be received by the Authority in payment for an equal value of the assets of the National Waterworks and Sewerage Authority.\nAny reference made to the Metropolitan Water District or to any existing government-owned waterworks and sewerage systems in any city, municipality or municipal district and any waterworks and sewerage system under the Bureau of Public Works, in any Act or Executive Order or Proclamation of the President of the Philippines or in any city or municipal ordinance which is still in force, shall be deemed to be a reference to the National Waterworks and Sewerage Authority created by this Act."}},{"id":"PH-H1217-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Possession by the Authority of all water and sewer systems within its territory; charging and collection of uniform rates. The National Waterworks and Sewerage Authority shall own and control all the water and sewer distributing systems of the City of Manila and the nearby municipalities comprising the Metropolitan Water District, as well as the water and sewer distributing systems of all other cities, municipalities and municipal districts in the Philippines, and shall charge and collect a uniform rate for all services rendered in each city, municipality, or municipal district, whether to any person, corporation, firm, government body, municipal entity or religious or charitable institutions: Provided , That the Public Service Commission shall exercise no control, supervision or jurisdiction whatsoever over the National Waterworks and Sewerage Authority in the fixing of rates or over its properties.\nThe Authority shall exist as an independent agency of the Government under the Department of Public Works and Communications for administrative purposes."}},{"id":"PH-H1217-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"National Subsidy for Non-Revenue Producing Water Systems and Sanitary Works. Non-self-supporting and/or non-revenue producing water systems and sanitary works, such as springs, artesian wells, and drainage systems, shall receive from the National Government a subsidy to be provided in the Annual Appropriation Acts for the construction, operation, maintenance, and control of those works once completed. The amount of the subsidy shall be determined by the Budget Commissioner who shall base such determination upon recommendation of the National Waterworks and Sewerage Authority. The accounting and disbursing of funds for this particular item of expense shall be undertaken separately in the account books of the Authority."}},{"id":"PH-H1217-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Letting of contracts for public works of the Authority. All construction and repair works authorized by the Authority, involving an estimated cost of ten thousand pesos or more, shall be let by the General Manager with the approval of the Board of Directors to contract under the usual bidding procedure of the Government, except in the case of construction or repair of water, sewer, and pipe lines or storm drains, and such other projects which, in the discretion of the Board, due to its urgent nature, should be undertaken by the Authority by administration."}},{"id":"PH-H1217-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Repeal or modification. All Acts, executive orders, administrative orders and proclamations or parts thereof consistent with any of the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H1217-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Effective date of this Act. This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1218"] = {"id":"PH-H1218","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1384_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Adopting Mr. Ray Higgins as Son of the Philippines, and Conferring Upon Him All the Rights, Privileges and Prerogatives of Philippine Citizenship","orig":"An Act Adopting Mr. Ray Higgins as Son of the Philippines, and Conferring Upon Him All the Rights, Privileges and Prerogatives of Philippine Citizenship"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 1384","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1384_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1218-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Mr. Ray Higgins, an American resident in the Philippines, is hereby adopted as son of the Philippines and conferred all the rights, privileges and prerogatives of Philippine citizenship."}},{"id":"PH-H1218-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1219"] = {"id":"PH-H1219","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1385_1955.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting Jose Borres a Franchise for an Electric Light, Heat and Power System in the Municipality of President Roxas, Province of Capiz","orig":"An Act Granting Jose Borres a Franchise for an Electric Light, Heat and Power System in the Municipality of President Roxas, Province of Capiz"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1385","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1385_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1219-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Jose Borres, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the Municipality of President Roxas, Province of Capiz."}},{"id":"PH-H1219-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1219-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that, in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender his franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1219-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1220"] = {"id":"PH-H1220","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1386_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Adopting the Honorable George A. Malcolm as Son of the Philippines and Conferring Upon Him All the Rights, Privileges and Prerogatives of Philippine Citizenship","orig":"An Act Adopting the Honorable George A. Malcolm as Son of the Philippines and Conferring Upon Him All the Rights, Privileges and Prerogatives of Philippine Citizenship"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 1386","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1386_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1220-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Honorable George A. Malcolm, of Concord, Michigan, is hereby adopted as son of the Philippines and conferred all the rights, privileges and prerogatives of Philippine citizenship."}},{"id":"PH-H1220-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1221"] = {"id":"PH-H1221","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1387_1955.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of the University of Mindanao in Dansalan City and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of the University of Mindanao in Dansalan City and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1387","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1387_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1221-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established in Dansalan City a university which shall be known as the University of Mindanao, the same being organized as a corporation under that name."}},{"id":"PH-H1221-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The said University shall primarily give professional and technical training, besides providing advanced instruction in literature, philosophy, the sciences, and arts."}},{"id":"PH-H1221-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"No student shall be denied admission to the University by reason of age, sex, nationality, religious belief, or political affiliation."}},{"id":"PH-H1221-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The government of said University is vested in a board of regents to be known as the Board of Regents of the University of Mindanao. The Board of Regents shall be composed of the Secretary of Education, who shall be ex officio chairman of the Board, the Chairman of the Committee on Education of the Senate, the Chairman of the Committee on Education of the House of Representatives, the President of the University, the Director of Public Schools, and seven additional members to be appointed by the President of the Philippines, with the consent of the Commission on Appointments: Provided, That as soon as there are enough graduates of the University of Mindanao, at least four of the additional members of its Board of Regents shall be selected from among the alumni of said University upon recommendation of the Alumni Association. The President of the University shall be elected and his compensation shall be fixed by the Board of Regents.\nOf the seven additional members first appointed as above provided, the President of the Philippines shall designate one to serve for one year, one to serve for two years, one to serve for three years, one to serve for four years, one to serve for five years, one to serve for six years, and one to serve for seven years. Thereafter persons appointed to succeed such members shall hold office for a term of seven years and until their successors are appointed. In case of a vacancy shall be filled by appointment by the President of the Philippines, with the consent of the Commission on Appointments, and such appointee shall hold office for the unexpired term only. All members of the Board of Regents shall be residents of the Philippines. No person in the employ of the University or in any other educational institution in any capacity whatsoever, whether as dean, professor, instructor, lecturer, or otherwise, shall be eligible for membership in the Board.\nMembers shall serve without compensation, but they shall be reimbursed for necessary expenses incurred either in attendance upon meetings of the Board or upon other official business authorized by resolution of the Board."}},{"id":"PH-H1221-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The University of Mindanao shall have the general powers set out in section thirteen of Act Numbered Fourteen hundred and fifty-nine, and the administration of said University and the exercise of its corporate powers are hereby vested exclusively in the Board of Regents, and in the President of the University in so far as authorized by said Board."}},{"id":"PH-H1221-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Board of Regents shall have the following powers and duties, in addition to its general powers of administration and the exercise of the powers of the corporation:\n(a) To receive and appropriate to the ends specified by law such sums as may be provided by law for the support of the University;\n(b) To provide for the establishment of one or more Colleges of Liberal Arts, a College of Law, a College of Social and Political Science, a College of Medicine and Surgery, a College of Pharmacy, a College of Dentistry, a College of Veterinary Science, a College of Engineering, a College of Agriculture, a College of Education, a College of Forestry, a College of Nursing, a School of Fine Arts, a Conservatory of Music, a School of Surveying, and such other colleges and schools as the Board of Regents may deem necessary;\n(c) To confer the usual honorary degrees upon persons in recognition of learning, statesmanship, or eminence in literature, science or art: Provided, That such degrees shall not be conferred in consideration of the payment of money or other valuable consideration;\n(d) To establish chairs in the colleges mentioned in paragraph (b), and to provide for the maintenance or endowment of such chairs, as well as to provide for such other professors, assistant professors, instructors, tutors, and lecturers as the progress of instruction may make necessary, and to fix the compensation pertaining to such positions;\n(e) To appoint, on the recommendation of the President of the University, professors, instructors, lecturers and other employees of the University; to fix their compensation, hours of service, and such other duties and conditions as it may deem proper; to grant to them in its discretion leave of absence under such regulations as it may promulgate, any provisions of law to the contrary notwithstanding, and to remove them for cause after an investigation and hearing shall have been had;\n(f) To approve the courses of study and rules of discipline drawn up by the University Council as hereinafter provided; to fix the tuition fees required of students, as well as matriculation fees, graduation fees and fees for laboratory courses, and all special fees; and to remit the same in special cases;\n(g) To provide fellowships and scholarships and to award the same to students showing special evidence of merit;\n(h) To prescribe rules for its own government, and to enact for the government of the University such general ordinances and regulations, not contrary to law, as are consistent with the purposes of the University as defined in section two of this Act;\n(i) To receive in trust legacies, gifts, and donations of real and personal property of all kinds and to administer the same for the benefit of the University, or of a department thereof, or for aid to any student or students, in accordance with the direction or instructions of the donor, and, in default thereof, in such manner as the Board of Regents may in its discretion determine."}},{"id":"PH-H1221-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"A quorum of the Board of Regents shall consist of a majority of all the members holding office at the time the meeting of the Board is called. All processes against the Board of Regents shall be served on the chairman or secretary thereof."}},{"id":"PH-H1221-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"On or before the tenth day of June of each year the Board of Regents shall file with the President of the Philippines a detailed report, setting forth the progress, condition, and needs of the University."}},{"id":"PH-H1221-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"There shall be a University Council, consisting of the President of the University and of all instructors in the University holding the rank of professor, associate professor, or assistant professor. The Council alone shall have the power to recommend students or others to be recipient of degrees. Through its president or committees it shall have the disciplinary power over the students within the limits prescribed by the rules of discipline approved by the Board of Regents. The powers and duties of the President of the University, in addition to those specifically provided for in this Act, shall be those usually pertaining to the office of the president of a university."}},{"id":"PH-H1221-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The body of instructors of each college shall constitute its faculty, and as presiding officer of each faculty there shall be a dean elected from the members of such faculty by the Board of Regents on nomination by the President of the University. In the appointment of professors or other instructors of the University, no religious test shall be applied, nor shall the religious opinions or affiliations of the instructors of the University be made a matter of examination or inquiry: Provided, However, That no instructor in the University shall inculcate sectarian tenets in any of the teachings, nor attempt, either directly or indirectly, under penalty of dismissal by the Board of Regents, to influence students or attendants at the University for or against any particular church or religious sect."}},{"id":"PH-H1221-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Professors and other regular instructors in the University shall be exempt as such from any civil service examination or regulation as a requisite to appointment."}},{"id":"PH-H1221-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"There shall be a secretary of the University, appointed by the Board of Regents. He shall be the secretary of such Board and also of the University, and shall keep such records of the University as may be designated by the Board."}},{"id":"PH-H1221-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The Treasurer of the Philippines shall be ex officio treasurer of the University, and all accounts and expenses thereof shall be audited by the Auditor General and all disbursements shall be made in accordance with the rules and regulations prescribed by him."}},{"id":"PH-H1221-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Heads of bureaus and offices of the National Government are hereby authorized to loan or transfer, upon request of the President of the University, such apparatus or supplies as may be needed by the University and to detail employees for duty therein, when in the judgment of the head of the bureau or office such supplies or employees can be spared without serious detriment to the public service. Employees so detailed shall perform such duty as is required under such detail, and the time so employed shall count as part of their regular official service."}},{"id":"PH-H1221-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The President of the Philippines, the President of the Senate, and the Speaker of the House of Representatives shall constitute a board of visitors of the University, whose duty it shall be to attend the commencement exercises of the University, and to make visits at such other times as they may deem proper, to examine the property, course of study, discipline, the state of finances of the University, to inspect all books and accounts of the institution, and to make report to the Congress of the Philippines upon the same, with such recommendations as they favor."}},{"id":"PH-H1221-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The sum of five hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to be expended in the discretion of the Board of Regents for the establishment of a college or colleges authorized by this Act, the establishment of which may be considered more urgent."}},{"id":"PH-H1221-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1222"] = {"id":"PH-H1222","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1388_1955.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Bacolor市","en":"An Act Converting the Pampanga Trade School in the Municipality of Bacolor, Province of Pampanga, into a Regional School of Arts and Trades to be Known as the Pampanga School of Arts and Trades, and to Authorize the Appropriation of Funds for the Purpose","orig":"An Act Converting the Pampanga Trade School in the Municipality of Bacolor, Province of Pampanga, into a Regional School of Arts and Trades to be Known as the Pampanga School of Arts and Trades, and to Authorize the Appropriation of Funds for the Purpose"},"level":"law","status":"active","topics":["trade","education","culture"],"docNumber":"Republic Act No. 1388","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1388_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1222-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Pampanga Trade School in the Municipality of Bacolor, Province of Pampanga, is hereby converted into a regional school of arts and trades, of the Philippine School of Arts and Trades type, to be known as the Pampanga School of Arts and Trades. The said school shall be under the supervision of the Bureau of Public Schools and subject to the provisions of the School Law. Courses of collegiate and secondary levels shall be offered in the said school."}},{"id":"PH-H1222-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the expenses of the said school during the fiscal year nineteen hundred fifty-six. Thereafter, the necessary funds for its operation and maintenance shall be included in the annual General Appropriation Acts."}},{"id":"PH-H1222-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1223"] = {"id":"PH-H1223","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1389_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Rizal市","en":"An Act Creating the Barrio of Bataan, Municipality of Rizal, Province of Zamboanga del Norte","orig":"An Act Creating the Barrio of Bataan, Municipality of Rizal, Province of Zamboanga del Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1389","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1389_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1223-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Sibacan in the barrio of La Libertad, Municipality of Rizal, Province of Zamboanga del Norte, is separated from the barrio of La Libertad, and constituted into an independent barrio of the said municipality, to be known as the barrio of Bataan."}},{"id":"PH-H1223-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1224"] = {"id":"PH-H1224","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1390_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Three Hundred Thousand Pesos as Aid to the Philippine Tuberculosis Society for the Improvement of its Present Buildings or the Construction of New Pavilions","orig":"An Act Appropriating the Sum of Three Hundred Thousand Pesos as Aid to the Philippine Tuberculosis Society for the Improvement of its Present Buildings or the Construction of New Pavilions"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1390","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1390_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1224-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of three hundred thousand pesos is appropriated, out of any funds in the National Treasury not otherwise appropriated as aid to the Philippine Tuberculosis Society for the improvement of its present buildings or the construction of new pavilions."}},{"id":"PH-H1224-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1225"] = {"id":"PH-H1225","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1391_1955.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Twenty-Five Thousand Pesos as Aid to the First Southeast Asia Music Conference to be Held in the City of Manila in August, Nineteen Hundred and Fifty-Five","orig":"An Act Appropriating the Sum of Twenty-Five Thousand Pesos as Aid to the First Southeast Asia Music Conference to be Held in the City of Manila in August, Nineteen Hundred and Fifty-Five"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1391","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1391_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1225-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of twenty-five thousand pesos is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, as aid to the First Southeast Asia Music Conference which will be held in Manila in August, nineteen hundred and fifty-five."}},{"id":"PH-H1225-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The funds herein appropriated shall be disbursed through the UNESCO National Commission of the Philippines with the approval of the President of the Philippines."}},{"id":"PH-H1225-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1226"] = {"id":"PH-H1226","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1392_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend Section Eleven of the Philippine Tariff Act of 1909 and Exempting Textiles Made of 100 Per Cent Philippine Ramie Fiber from the Payment of Duty to Provide Incentives for the Development of the Ramie Industry","orig":"An Act to Amend Section Eleven of the Philippine Tariff Act of 1909 and Exempting Textiles Made of 100 Per Cent Philippine Ramie Fiber from the Payment of Duty to Provide Incentives for the Development of the Ramie Industry"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1392","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-08-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1392_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1226-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eleven of the Philippine Tariff Act of 1909 is hereby amended by adding thereto another paragraph to read as follows:\n\"355. Ramie threads, yarns, textiles and industrial fabrics hereinafter also called ramie goods, when processed abroad from 100 per cent ramie fiber grown in the Philippines and bought direct from farmers-producers or any of their cooperatives by any government agency designated by the President of the Philippines and by it exported abroad in exchange therefor when their importation is made through the government agency so designated by the President: Provided , That such tax-exempt importation herein contemplated shall be allocated proportionately among the original farmer-producers or any of their cooperatives from whom the government agency herein specified obtained the ramie fiber for processing abroad.\n\"The exemption above granted shall cease two years after the date of approval of this amendatory Act or at any earlier date upon proclamation of the President on recommendation of the National Economic Council to the effect that sufficient degumming, spinning and/or weaving mills to process the entire production of ramie fiber shall have been established in the country.\""}},{"id":"PH-H1226-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: August 23, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1227"] = {"id":"PH-H1227","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1393_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Facilitate the Entry into the Philippines as International Traders of Nationals of the United States","orig":"An Act to Facilitate the Entry into the Philippines as International Traders of Nationals of the United States"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1393","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-08-29","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1393_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1227-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Upon a basis of reciprocity, a national of the United States and the spouse and children of any such national, if accompanying or following to join him, may, if otherwise eligible for a visa and if otherwise admissible under Commonwealth Act Numbered Six hundred thirteen, otherwise known as the Philippine Immigration Act of Nineteen hundred forty, as amended, be considered to be classifiable as a non-immigrant under section nine (d) of said Act if entering (a) solely to carry on substantial trade principally between the Philippines and the United States, or (b) solely to develop and direct the operations of an enterprise in which he has invested, or of an enterprise in which he is actively in the process of investing, a substantial amount of capital."}},{"id":"PH-H1227-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: August 29, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1228"] = {"id":"PH-H1228","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1394_1955.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Impose a Special Import Tax on All Goods, Articles or Products Imported or Brought into the Philippines, and to Repeal Republic Acts Numbered Six Hundred and One, Eight Hundred and Fourteen, Eight Hundred and Seventy-One, Eleven Hundred and Seventy-Five, Eleven Hundred and Ninety-Seven and Thirteen Hundred and Seventy-Five","orig":"An Act to Impose a Special Import Tax on All Goods, Articles or Products Imported or Brought into the Philippines, and to Repeal Republic Acts Numbered Six Hundred and One, Eight Hundred and Fourteen, Eight Hundred and Seventy-One, Eleven Hundred and Seventy-Five, Eleven Hundred and Ninety-Seven and Thirteen Hundred and Seventy-Five"},"level":"law","status":"active","topics":["tax","trade"],"docNumber":"Republic Act No. 1394","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-08-29","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1394_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1228-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Except as herein otherwise provided, there shall be levied, collected and paid a special import tax on all goods, articles or products imported or brought into the Philippines, irrespective of source, during the period and in accordance with the rates provided for in the following schedule:\n(1) Calendar year 1956, seventeen per cent;\n(2) Calendar year 1957, fifteen and three-tenths per cent;\n(3) Calendar year 1958, thirteen and six-tenths per cent;\n(4) Calendar year 1959, eleven and nine-tenths per cent;\n(5) Calendar year 1960, ten and two-tenths per cent;\n(6) Calendar year 1961, eight and five-tenths per cent;\n(7) Calendar year 1962, six and eight-tenths per cent;\n(8) Calendar year 1963, five and one-tenth per cent;\n(9) Calendar year 1964, three and four-tenths per cent; and\n(10) Calendar year 1965, one and seven-tenths per cent: Provided, however , That this Act does not repeal the specific and compensating taxes on imported goods."}},{"id":"PH-H1228-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"(a) Notwithstanding the provisions of section one of this Act, if as a result of the application of the schedule therein, the total revenue derived from the customs duties and from the special import tax on goods, articles or products imported from the United States is less in any calendar year than the proceeds from the exchange tax imposed under Republic Act Numbered Six hundred and one, as amended, on such goods, articles or products during the calendar year 1955, the President may, by proclamation, suspend the reduction of the special import tax for the next succeeding calendar year as prescribed in the schedule, and, in order to restore the total revenue to be collected on the importation of United States goods, articles or products to the level of the exchange tax thereon during the calendar year 1955, increase the special import tax on all goods coming from any country for such succeeding calendar year to any previous rate provided for in this Act which is deemed necessary to restore the said revenue to the level attained in calendar year 1955.\n(b) After the President shall have made adjustments in the rate of tax for any given year in accordance with paragraph (a) of this section, the tax to be imposed in subsequent years shall be as provided for the corresponding year in the schedule in section one: Provided , That the President may impose any higher rate of tax within the schedule other than that fixed for the corresponding year in order to cover anticipated deficiency in revenue arising from the operation of this Act."}},{"id":"PH-H1228-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The value for assessment of the special import tax on goods, articles or products shall be the price at which, at the time of exportation, those goods, articles or products or one of the same kind is offered for sale in the exporting country, in the usual wholesale quantities and in the ordinary course of trade excluding internal excise taxes to be remitted or rebated, plus ordinary expenses prior and incidental to the lading of such goods, articles or products on board the vessel at the port of export including taxes or duties, if any, and ordinary freight as well as ordinary insurance covering the transportation of such goods, articles or products to the port of entry."}},{"id":"PH-H1228-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The special import tax shall be paid by the importer to the Bureau of Customs in accordance with regulations to be promulgated by the Department of Finance and prior to the release of the imported goods, articles or products from customs custody."}},{"id":"PH-H1228-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Republic Act Numbered Six hundred and one, as amended, is hereby repealed."}},{"id":"PH-H1228-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The tax provided for in section one of this Act shall not be imposed against the importation into the Philippines of machinery and/or raw materials to be used by new and necessary industries as determined in accordance with Republic Act Numbered Nine hundred and one; cattle; canned milk, canned beef, canned salmon and sardines, cocoa beans, malt, stabilizer and flavors, vitamin concentrate; supplies and equipment purchased directly by the Government or any of its instrumentalities for its own exclusive use; machinery, equipment, accessories, and spare parts, for the use of industries, miners, mining enterprises, planters and farmers; and fertilizers when imported by planters or farmers directly or through their cooperatives; spare parts to be used in the repair of vessels of Philippine registry or airplanes and such other parts thereof as may be certified by the Hulls and Boilers Division of the Bureau of Customs or the Civil Aeronautics Administration, respectively, as essential to the maintenance of vessels or airplanes; vessels or ships of any kind or nature intended for Philippine registry, sixty per cent of the ownership of which belongs exclusively to Filipinos; articles or containers used, including materials for the manufacture of tin containers used by the importer himself in the manufacture or preparation of local products for consignment or export abroad; textbooks, reference books, and supplementary readers approved by the Board on Textbooks and/or established public or private educational institutions; paper and newsprint imported by publishers for their exclusive use in the publication of books, pamphlets, magazines and newspapers; cyanide, explosives and dynamite for mining purposes; drugs and medicines, medical, dental and hospital supplies enumerated as follows:\nDRUGS AND MEDICINES\n1. Amebacides, except emetine preparations.\n2. Amino acid preparations and analgesic poultices.\n3. Anaesthetics, all types.\n4. Antiacids, absorbents, and preparations.\n5. Antibiotics and preparations, except dosage forms of penicillin, streptomycin and/or combinations.\n6. Anticholinergic preparations.\n7. Anticoagulants.\n8. Anti-leprosy preparations.\n9. Antimalarias, except quinine preparations.\n10. Antispasmodic, anticonvulsant, and sympathomimetic preparations.\n11. Antitoxins, vaccines, sera, toxoids, and antigens.\n12. Dehydrated milks and homogenized baby foods.\n13. Diagnostic and laboratory reagents.\n14. Digitalis and preparations.\n15. Drugs (crude or otherwise), chemicals (simple or compound) for pharmaceutical manufacture.\n16. Drugs and medicines for the use of the dental and veterinary professions.\n17. Ergot and preparations.\n18. Fumigants, disinfectants, and preparations.\n19. Gland products and synthetic substitutes.\n20. Hemostatics for topical use.\n21. Hexylresorcinol preparations.\n22. Insulin, all forms.\n23. Liver extract.\n24. Mercurial Diuretics.\n25. Narcotics and hypnotics, natural or synthetic, and preparations.\n26. Pharmaceutical glassware and containers not manufactured locally.\n27. Plasma.\n28. Saccharin and substitutes.\n29. Salt substitutes.\n30. Steroids and preparations.\n31. Surgical antiseptics.\nMEDICAL, DENTAL AND HOSPITAL SUPPLIES\n1. Adhesives, plasters, bandages, gauzes, and dressings.\n2. Cottons, absorbents or synthetic substitutes.\n3. Dental instruments, equipment and supplies.\n4. Diagnostic instruments.\n5. Hospital and surgical rubber goods including catheters.\n6. Electro-medical therapy equipment.\n7. Optometric instruments and supplies.\n8. Surgical instruments, equipment and supplies, including operating lights and sterilizers, except examining and treatment tables.\n9.&#9X-Ray equipment, films and supplies.\n10. Radium and radioactive materials for therapy.\n11. Spare parts for dental, electro-medical, therapy and X-Ray equipment.\n12. Supplies and equipment to be used exclusively by the Blood Bank of the Philippine Red Cross.\n13. Not more than two new well-tested drugs authorized by the Secretary of Health each year upon the recommendation of the Philippine Medical Association and the Philippine Federation of Private Medical Practitioners."}},{"id":"PH-H1228-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect on January 1, 1956: Provided, That on or before said date, the President shall have previously declared by proclamation the taking effect of a trade agreement between the Philippines and the United States revising the Executive Agreement on Trade and Related Matters between the President of the Philippines and the President of the United States dated July 4, 1946, failing which this Act shall have no force and effect.\nApproved: August 29, 1955"}}],"pack":"ph-p17"};
  FT["PH-H1229"] = {"id":"PH-H1229","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1395_1955.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Authorizing the President of the Philippines to Issue Bonds in the Amount of Ten Million Pesos, Under the Provisions of Republic Act Numbered One Thousand, to Finance Cadastral Surveys Throughout the Philippines, and Authorizing the Director of Lands to Take Measures to Insure Collection of the Survey Costs and Other Charges","orig":"An Act Authorizing the President of the Philippines to Issue Bonds in the Amount of Ten Million Pesos, Under the Provisions of Republic Act Numbered One Thousand, to Finance Cadastral Surveys Throughout the Philippines, and Authorizing the Director of Lands to Take Measures to Insure Collection of the Survey Costs and Other Charges"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1395","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-08","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1395_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1229-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The President of the Philippines is hereby authorized to issue in the name and in behalf of the Republic of the Philippines bonds in an amount not exceeding ten million pesos, under the provisions of Republic Act Numbered One thousand. The proceeds from the sale of the bonds are hereby appropriated to be deposited with the Treasurer of the Philippines and to be disbursed to cover all expenses which may be incurred by the Bureau of Lands in the execution of cadastral surveys."}},{"id":"PH-H1229-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"With the approval of the Secretary of Agriculture and Natural Resources, the Director of Lands may award any cadastral survey under this Act to private land surveys or corporations engaged in survey work offering the most reasonable bid therefor."}},{"id":"PH-H1229-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Any property surveyed from the fund created under this Act shall be liable to the payment of the proportionate survey cost and other charges as provided for in sections 18(a), 18(b), 18(c), 18(d), and 18(e) of the Cadastral Act (Act 2259): Provided, That within one year after default of payment on an installment on the proportionate survey cost and other charges for which the property is liable, the Director of Lands shall file with the Clerk of the Court of First Instance of the province or city where the land is located a list of all lands upon which default has been made. The Clerk of Court shall thereupon publish in the manner provided for the publication of the summons in a civil action the list of the lands so filed by the Director of Lands, accompanied by a notice requiring the owners to answer within thirty days after the completion of the publication and setting the date the cases shall be heard.\nAfter due hearing, judgment with costs shall be entered against the owners of the lands found delinquent in the payment of survey costs and other charges, and said lands or such portions thereof as may be found necessary shall be sold by the Sheriff in a public auction after ten days’ notice. The proceeds thereof shall be applied to the payment of the installments due on the survey costs and other charges, and any excess over the amounts applied, shall be delivered to the owner. Within one year from the date of the sale, the owner may redeem the land by paying the price for which the land has been sold with interest at six per centum per annum."}},{"id":"PH-H1229-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Any amount paid on account of the cost of survey authorized under this Act shall be deposited in the National Treasury to the credit of the fund herein created."}},{"id":"PH-H1229-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Any law or parts of law inconsistent herewith are hereby repealed."}},{"id":"PH-H1229-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 8, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1230"] = {"id":"PH-H1230","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1396_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Fifty Million Pesos, Out of the Proceeds of the Bond Issue Authorized by Republic Act Numbered One Thousand, to Finance the Establishment of One or More Pig Iron Smelting Plants by the National Shipyards and Steel Corporation, and to Provide Said Corporation with Operating Capital","orig":"An Act Appropriating the Sum of Fifty Million Pesos, Out of the Proceeds of the Bond Issue Authorized by Republic Act Numbered One Thousand, to Finance the Establishment of One or More Pig Iron Smelting Plants by the National Shipyards and Steel Corporation, and to Provide Said Corporation with Operating Capital"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1396","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-08","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1396_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1230-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Out of the proceeds of the bond issue authorized under Republic Act Numbered One thousand, there is hereby appropriated the sum of fifty million pesos for the National Shipyards and Steel Corporation, forty-five million pesos of which shall be used to finance the establishment of one or more pig iron smelting plants, at such place or places as it deems convenient, and the balance of five million pesos to be used for the initial operating expenses of the pig iron smelting plants: Provided, however , That if coal is needed, native coal shall be used in connection with the operation thereof: Provided, further , That only one pig iron smelting plant shall first be established and no additional plant shall be put up until the first one shall have been fully established and operated: And provided, finally , That the National Economic Council shall determine and approve the sites where the smelting plants shall be established."}},{"id":"PH-H1230-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 8, 1955"}}],"pack":"ph-p17"};
  FT["PH-H1231"] = {"id":"PH-H1231","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1397_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend Section Two (k) of Commonwealth Act Numbered One Hundred Twenty, Entitled “An Act Creating the National Power Corporation, Prescribing its Powers and Activities, Appropriating the Necessary Funds Therefor, and Reserving the Unappropriated Public Waters for its Use,” as Amended by Section One of Republic Act Numbered Three Hundred Fifty-Eight","orig":"An Act to Amend Section Two (k) of Commonwealth Act Numbered One Hundred Twenty, Entitled “An Act Creating the National Power Corporation, Prescribing its Powers and Activities, Appropriating the Necessary Funds Therefor, and Reserving the Unappropriated Public Waters for its Use,” as Amended by Section One of Republic Act Numbered Three Hundred Fifty-Eight"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1397","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-08","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1397_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1231-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two (k) of Commonwealth Act Numbered One hundred and twenty, as amended by section one of Republic Act Numbered Three hundred and fifty-eight, is further amended to read as follows:\n\"(k) When essential to the proper administration of its corporate affairs or necessary for the proper transaction of its business or to carry out the purposes for which it was organized, to contract indebtedness and issue bonds subject to the approval of the President of the Philippines upon the recommendation of the National Economic Council. The total indebtedness of the Corporation, of all classes, shall not at any time exceed five hundred million pesos, and the issue of bonds shall be subject to the conditions set forth in section four of this Act. All projects to be financed with funds accruing from this increased indebtedness shall be approved by the National Economic Council: Provided, However , That in distributing and allocating the output produced by the National Power Corporation, the needs and requirements of the different users thereof whether for public utility, industrial or otherwise should be taken into account and a just and equitable distribution and allocation thereof should be made, giving preference to the need of the adjacent areas: And Provided, further, That areas traversed by transmission lines shall be allocated electricity proportionate to the needs of the areas.\""}},{"id":"PH-H1231-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 8, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1232"] = {"id":"PH-H1232","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1398_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Twenty Million Pesos to Implement Republic Act Numbered Eight Hundred Ninety-Nine Which Created a Revolving Fund for the Construction, Reconstruction or Improvement of Irrigation Systems","orig":"An Act Appropriating the Sum of Twenty Million Pesos to Implement Republic Act Numbered Eight Hundred Ninety-Nine Which Created a Revolving Fund for the Construction, Reconstruction or Improvement of Irrigation Systems"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1398","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-08","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1398_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1232-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of twenty million pesos is hereby appropriated, from the amount authorized under Republic Act Numbered One thousand or any other Act of similar nature, which shall constitute the revolving fund created under Republic Act Numbered Eight hundred ninety-nine, for the construction, reconstruction or improvement of irrigation systems as approved by the National Economic Council and in accordance with the provisions of said Republic Act Numbered Eight hundred ninety-nine."}},{"id":"PH-H1232-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 8, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1233"] = {"id":"PH-H1233","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1399_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend Section Two Hundred Seventy-One of the Revised Administrative Code, as Amended, Relative to Vacation Leave of Judges of First Instance","orig":"An Act to Amend Section Two Hundred Seventy-One of the Revised Administrative Code, as Amended, Relative to Vacation Leave of Judges of First Instance"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 1399","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-08","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1399_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1233-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two hundred seventy-one of Act Numbered Twenty-seven hundred and eleven, as amended by Commonwealth Act Numbered Two hundred and twenty, is further amended to read as follows:\n\"Sec. 271. Leave of absence of Judges of First Instance. -During the yearly court vacation, the judges of first instance not specially assigned to vacation duty shall be upon vacation leave. In case of those who are assigned to vacation duty, they shall be entitled to vacation leave at any subsequent time for the same number of days that they spend on vacation duty but not exceeding one month per year, said leave being cumulative; but the total amount of leave that can accumulate to the credit of a judge of first instance at any one time shall not exceed ten months, which said judge may enjoy, including the one month of court vacation or the one month’s leave in lieu thereof, if, in the opinion of the Department Head, the exigencies of the service permit.\""}},{"id":"PH-H1233-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 8, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1234"] = {"id":"PH-H1234","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1400_1955.html","fetchedAt":"2026-10-06","articleCount":30,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Defining a Land Tenure Policy, Providing for an Instrumentality to Carry Out the Policy, and Appropriating Funds for its Implementation","orig":"An Act Defining a Land Tenure Policy, Providing for an Instrumentality to Carry Out the Policy, and Appropriating Funds for its Implementation"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1400","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-09","completenessNote":"全文，共 30 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1400_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 30 条，缺 3）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。 源文存在同号重出的条款（第 2 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1234-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short title. This Act shall be known as the \"Land Reform Act of 1955.\""}},{"id":"PH-H1234-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of policy. It is the declared policy of the State to create and maintain an agrarian system which is peaceful, prosperous and stable, and to this end the Government shall establish and distribute as many family-size farms to as many landless citizens as possible through the opening up of public agricultural lands and the division and distribution of private agricultural lands where agrarian conflicts exist, either by private arrangement with the owners or through expropriation proceedings.\nTHE LAND TENURE ADMINISTRATION"}},{"id":"PH-H1234-A2_2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Creation and composition. For the purpose of carrying out the policy enunciated in this Act, there is hereby created a Land Tenure Administration, hereinafter called the Administration, which shall be directly under the control and supervision of and responsible to the President of the Philippines. The Administration shall consist of a Chairman and two members who shall be appointed by the President with the consent of the Commission on Appointments and shall hold office for a period of five years. They may be removed for cause or for incapacity to discharge the duties of their office."}},{"id":"PH-H1234-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Qualifications and compensation of members. No person shall be appointed Chairman or member of the Administration unless he is natural born citizen of the Philippines, at least thirty-five years of age, and not related by affinity or consanguinity within the fourth civil degree to any landowner who may be affected by this Act.\nThe Chairman shall receive an annual compensation of fifteen thousand pesos and the members shall each receive an annual compensation of twelve thousand pesos."}},{"id":"PH-H1234-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Functions. It shall be the responsibility of the Administration to:\n(1) Make studies on the land tenure problems throughout the Philippines, prepare over-all long range plans to solve such problems, and keep the President and the Congress of the Philippines fully informed of the progress of the land tenure reform program;\n(2) Initiate immediate investigation in areas reporting land tenure difficulties and recommend appropriate action without delay;\n(3) Inform the President and the Congress of the Philippines of any deficiency of the other departments or agencies of the Government in the implementation of legislation bearing on or affecting the land tenure reform;\n(4) Prepare a plan for the systematic opening of virgin lands of the public domain for distribution to tenants, preference to be given to those tenants who are ejected by virtue of mechanization and to other landless citizens; and\n(5) To implement and carry out the expropriation and the resale or lease of urban lands already authorized by existing laws."}},{"id":"PH-H1234-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Powers. In pursuance of the policy enunciated in section two hereof, the Administration is authorized to:\n(1) Purchase private agricultural lands for resale at cost to bona fide tenants or occupants, or in the case of estates abandoned by the owners for the last five years, to private individuals who will work the lands themselves and who are qualified to acquire or own lands but who do not own more than six hectares of lands in the Philippines;\n(2) Initiate and prosecute expropriation proceedings for the acquisition of private agricultural lands in proper cases, for the same purpose of resale at cost: Provided , That the power herein granted shall apply only to private agricultural lands as to the area in excess of three hundred hectares of contiguous area if owned by natural persons and as to the area in excess of six hundred hectares if owned by corporations: Provided, further , That land where justified agrarian unrest exists may be expropriated regardless of its area.\n(3) Prepare a schedule of areas of family-size farm units, not exceeding six hectares each, for different crops in different localities; and\n(4) Promulgate such rules and regulations as may be necessary for the successful implementation of the provisions of this Act."}},{"id":"PH-H1234-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Appointment of subordinate officials and employees. To enable the Administration to implement the provisions of this Act more effectively, it shall have a Legal Staff, a Technical Staff and a Financial Staff, the personnel of which shall be appointed by the Administration which shall also fix their compensation.\nThe Administration shall appoint, subject to Civil Service rules and regulations, fix the compensation and determine the duties of such officials and employees as the exigencies of the service may require. The Administration shall establish and prescribe its own rules, regulations, standards and records for the employment, promotion, transfer, welfare and compensation of employees and officers of the Administration and provide a system of organization to for responsibility and promote efficiency."}},{"id":"PH-H1234-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Assistance of other departments and agencies. The Administration may call upon any department or agency of the Government for assistance and cooperation on any matter connected with the functions and powers of the Administration.\nNEGOTIABLE LAND CERTIFICATES"}},{"id":"PH-H1234-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Issuance. The President, for the purposes provided for in this Act and upon recommendation of the Secretary of Finance and concurred in by the Monetary Board, is hereby authorized to issue negotiable land certificates upon the request of the Administration: Provided , That only sixty million a year will be issued during the first two years, and thirty million each year during the succeeding years.\nNegotiable land certificates shall be issued in denomination of one thousand pesos or multiples of one thousand pesos and shall be payable to bearer on demand and presentation at the Central Bank. These certificates if presented for payment after five years from the date of issue shall earn interest at the rate of four per centum per annum; if presented for payment after ten years from the date of issue shall earn interest at the rate of four and one-half per centum per annum; and if presented for payment after fifteen years from the date of issue shall earn interest at the rate of five per centum per annum."}},{"id":"PH-H1234-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Uses of certificates. Negotiable land certificates may be used by the holder thereof for any of the following purposes:\n(1) Payment for agricultural lands or other properties purchased from the Government: Provided, however , That in the case of purchase of agricultural lands, the purchaser is not otherwise prohibited to own or hold agricultural lands under the Constitution;\n(2) Payment for the purchase of shares of stock or of the assets of any industrial or commercial corporations owned or controlled by the Government;\n(3) Payment of all tax obligations of the holder thereof, or of any debt or monetary obligation of the holder to the Government or any of its instrumentalities or agencies, including the Rehabilitation Finance Corporation and the Philippine National Bank: Provided, however , That payment of indebtedness shall not be less that twenty per centum of the total indebtedness of the debtor; and\n(4) As surety or performance bonds, in all cases where the Government may require or accept real property as bonds.\nNEGOTIATED PURCHASE OF PRIVATE AGRICULTURAL LANDS"}},{"id":"PH-H1234-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Lands subject to the purchase. The Administration, acting for and on behalf of the Government, may negotiate to purchase any privately owned agricultural land when the majority of the tenants therein petition for such purchase."}},{"id":"PH-H1234-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Action on the petition. Upon receipt of the petition, the Administration shall;\n(1) Within thirty days, determine on the basis of the information contained in the petition, the suitability of the land for purchase, notify the petitioners and the landowner accordingly, and fix the date for preliminary negotiation;\n(2) Within sixty days from the preliminary negotiation, conduct investigations and technical surveys to determine title to the land and its real value, taking into account (a) the prevailing prices of similar lands in the immediate area, (b) the soil conditions topography and climate hazards, (c) actual production, (d) accessibility, and (e) improvements; and\n(3) Fix, within ninety days from the preliminary negotiation, the date for final negotiation."}},{"id":"PH-H1234-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Deposit by tenants. Before fixing the date for final negotiation under section twelve, paragraph (3), and in the interest of public welfare, the Administration shall require the tenants to form a cooperative to be affiliated with a government financing cooperative agency. Such cooperative agency shall deposit with the Administration an amount not exceeding twenty-five per centum of the annual gross produce of the principal crop or crops of such land on the basis of the average of harvest of the three years immediately preceding the year the petition was filed. This deposit shall be credited to the selling price to the tenants in accordance with the individual contribution of each to said deposit."}},{"id":"PH-H1234-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Payment. In negotiating for the purchase of agricultural land, the Administration shall offer to pay the purchase price wholly in land certificates or partly in legal tender and partly in land certificates: Provided , That the amount to be paid in legal tender shall in no case exceed fifty per centum of the purchase price: Provided, further , That the landowner, if he desires and the Administration so agrees, may be paid, by way of barter or exchange, with such residential, commercial or industrial land owned by the Government as may be agreed upon by the parties."}},{"id":"PH-H1234-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Outstanding debts of tenants. In cases where the landowner is willing to accept payment wholly in land certificates, the Administration is authorized to include in the price to be paid the landowner all the outstanding debts, evidenced in writing, of the tenants to said landowner, the Administration to be thereafter reimbursed in accordance with such rules and regulations as it may promulgate: Provided , That the resulting increase in price by virtue of such inclusion will not be more than ten per centum of the total cost of the land agreed upon in the negotiated sale.\nEXPROPRIATION OF PRIVATE AGRICULTURAL LANDS"}},{"id":"PH-H1234-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"When proper. The Administration may initiate and prosecute expropriation proceedings for the acquisition of private agricultural land subject to the provisions of section six, paragraph (2), upon petition of a majority of the tenants and after it is convinced of the suitability of such land for subdivision into family-size farm units, and that public interest will be served by its immediate acquisition, when any of the following conditions exists:\n(1) That the landowner falling within the terms of section six, paragraph (2), continues to refuse to sell after all efforts have been exhausted by the Administration to negotiate for its purchase; or\n(2) That the landowner is willing to sell under sections eleven and twelve but cannot agree with the Administration as to the price and/or the manner of its payment."}},{"id":"PH-H1234-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Petition. The petition, in case the landowner refuses to sell, shall be filed in the manner and form to be prescribed by the Administration. However, before initiating expropriation proceedings, the Administration shall make one last effort to purchase the land by negotiated sale."}},{"id":"PH-H1234-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Possession of the land; procedure. The Administration after commencing the expropriation suit may take immediate possession of the land upon deposit, with the Court which has acquired jurisdiction over the expropriation, of money or a certificate of deposit of a depository of the Republic of the Philippines as provided in section three of Rule 69 of the Rules of Court equal to the value of the land as provisionally and promptly determined by the Court taking into consideration the factors mentioned in section twelve, paragraph (2).\nThereafter the procedure in the Rules of Court with respect to eminent domain proceedings shall be followed. Pending judicial expropriation proceedings the owner of the land sought to be expropriated shall be given annually such allowance as his latest income tax return, prior to the institution of the proceedings, shows to be his net income from the land. Such allowance shall be approved by the court having jurisdiction and shall be deducted from the final amount awarded as compensation to the owner."}},{"id":"PH-H1234-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Payment. After the court has made a final determination of the just compensation for the land expropriated, it shall be paid wholly in cash unless the landowner chooses to be paid wholly or partly in land certificates, in which case section fifteen shall apply."}},{"id":"PH-H1234-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Prohibition against alienation. Upon the filing of the petition referred to in sections twelve and sixteen, the landowner cannot alienate any portion of the land covered by such petition except in pursuance of the provisions of this Act, or enter into any form of contract to defeat the purposes of this Act, and no ejectment proceedings against any tenant or occupant of the land covered by the petition shall be instituted or prosecuted until it becomes certain that the land shall not be acquired by the Administration.\nGENERAL PROVISIONS"}},{"id":"PH-H1234-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Resale of lands purchased or expropriated subject to condition. It shall be a condition in all resale contracts and annotated on the Torrens titles of lands acquired and subdivided by authority of this Act that said lands shall not be subdivided, sold or in any manner transferred or encumbered without prior consent of the Administration and only to qualified farmers or tenants or to government banking institutions or agencies."}},{"id":"PH-H1234-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Exemption from tax. All land certificates issued by authority of this Act shall be exempt from all forms of taxes. The purchase price paid by the Government for any agricultural land acquired for resale to tenants under the authority of this Act, whether through negotiation or expropriation, shall not be considered as income of the landowner concerned for purposes of the income tax."}},{"id":"PH-H1234-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Definition of terms. For the purposes of this Act, the following terms are defined as follows:\n(1) Agricultural lands shall mean lands devoted to agricultural production and shall include the farm home lots.\n(2) Family-size farm units shall mean such area of farm land not exceeding six hectares as will permit the efficient use of the labor resources of the farm family, taking into account the addition of such supplementary labor as may be necessary either for seasonal peak loads or during the developmental and transitional stages of the family itself.\n(3) At cost shall mean the purchase price plus six per cent interest per annum for twenty-five years which includes the one per cent per annum for administration expenses, plus actual expenses for survey, subdivision and registration. The total, divided into twenty-five equal installments, shall be the annual cost to the tenant for twenty-five years."}},{"id":"PH-H1234-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Payment of family-size farms sold to veterans and other government employees. Veterans of the Armed Forces of the Philippines and other government employees with backpay certificates from the Government are hereby authorized to use their backpay certificates in payment of family-size farms that may be acquired by them by authority of this Act."}},{"id":"PH-H1234-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Trust fund. All collections from the redistribution of the lands acquired by the Administration, after deducting the one per cent for administration expenses and the actual expenses for survey, subdivision and registration, shall be kept in the National Treasury as a special trust fund to be used exclusively for the redemption of the land certificates and bonds issued by authority of this Act."}},{"id":"PH-H1234-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Sinking fund; appropriation. A sinking fund shall be established in such manner that the total annual contribution thereto, accrued at such rate of interest as may be determined by the Secretary of Finance in consultation with the Monetary Board, shall be sufficient to redeem at maturity the land certificates and bonds issued under this Act. Said fund shall be under the custody of the Central Bank for which shall invest the same in such manner as the Monetary Board may approve; shall charge all expenses of such investment to said sinking fund; and shall credit the same with the interest on investments and other income belonging to it.\nA standing annual appropriation not exceeding twenty million pesos is hereby made out of the general fund in the National Treasury to provide for the sinking fund created in this section and to carry into effect the purposes of this Act.\nIn addition, there is hereby appropriated out of the bond issue authorized under Republic Act Numbered One thousand, the sum of one hundred million pesos to carry out the provisions of this Act."}},{"id":"PH-H1234-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Appropriation for the Administration. There is hereby appropriated out of any funds in the National Treasury not otherwise appropriated, the sum of three hundred thousand pesos for salaries, per diems, traveling expenses, furniture, office supplies and other expenses that may be incurred by the Administration for the fiscal year 1955-1956. The expenses of the Administration for the succeeding years shall be provided for in the corresponding annual general appropriation acts."}},{"id":"PH-H1234-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Transfer of functions of the Division of Landed Estates, Bureau of Lands. Upon the organization of the Administration, the Division of Landed Estates in the Bureau of Lands shall stand abolished and its functions, powers and duties, personnel, records, equipment and balances of appropriation shall thereupon be transferred to the said Administration."}},{"id":"PH-H1234-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Repeal of laws. All acts or parts of acts which are inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H1234-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Effectivity. This Act shall take effect upon its approval.\nApproved: September 9, 1955"}}],"pack":"ph-p17"};
  FT["PH-H1235"] = {"id":"PH-H1235","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1401_1955.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Manila市","en":"An Act Creating a Juvenile and Domestic Relations Court in the City of Manila, Amending for This Purpose Republic Act Numbered Four Hundred and Nine, Otherwise Known as the Charter of the City of Manila","orig":"An Act Creating a Juvenile and Domestic Relations Court in the City of Manila, Amending for This Purpose Republic Act Numbered Four Hundred and Nine, Otherwise Known as the Charter of the City of Manila"},"level":"law","status":"active","topics":["judiciary","civil"],"docNumber":"Republic Act No. 1401","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-09","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1401_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1235-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Republic Act Numbered Four hundred and nine is amended by inserting between sections thirty-eight and thirty-nine thereof a new Article, to be known as Article VIII-A, to read as follows:\n\"ARTICLE VIII-A The Juvenile and Domestic Relations Court \"Sec. 38-A. The Juvenile and Domestic Relations Court. There shall be a Juvenile and Domestic Relations Court in the City of Manila for which a judge who shall possess the same qualifications, enjoy the same privileges and receive the same salary as judges of courts of first instance, shall be appointed by the President of the Philippines with the consent of the Commission on Appointments.\n\"Provisions of the Judiciary Act to the contrary notwithstanding, the court shall have exclusive original jurisdiction to hear and decide the following cases after the effectivity of this Act:\n\"(a) Criminal cases cognizable by the Municipal Court and the Court of First Instance of Manila wherein the accused is under sixteen years of age at the time of the trial;\n\"(b) Cases involving custody, guardianship, adoption, paternity and acknowledgment;\n\"(c) Annulment of marriages, legal separation of spouses, and action for support;\n\"(d) Proceedings brought under the provisions of articles one hundred sixteen, two hundred twenty-five, two hundred fifty-two and three hundred thirty-two of the Civil Code;\n\"(e) Petitions for the declaration of absence and for the change of name;\n\"(f) Actions for the separation of property of spouses;\n\"(g) Proceedings affecting a dependent or neglected child, as hereinafter defined.\n\"The court shall likewise have such incidental powers as are generally possessed by courts of first instance.\n\"If any question involving any of the above matters should arise as an incident in any case pending in the ordinary courts, said incident shall be determined in the main case.\n\"Sec. 38-B. \"Dependent\" or \"neglected\" child defined. The term \"dependent child\" or \"neglected child\" shall mean any child under sixteen years of age who is dependent upon the public for support or who is destitute, homeless or abandoned; or who has no proper parental care or guardianship, or who habitually begs or receives alms, or who is found living in any house of ill fame or with any vicious or disreputable person, or whose home, by reason of neglect, cruelty or depravity on the part of its parents, guardian or other person in whose care it may be, is an unfit place for such child.\n\"Sec. 38-C. Proceedings concerning a \"dependent\" or \"neglected\" child. The Social Welfare Administrator or his representative who is a resident of the city, having knowledge of a child in the city who appears to be a \"dependent\" or \"neglected\" child may file with the clerk of the court a written petition, setting forth the facts constituting the child \"dependent\" or \"neglected;\" which petition shall be verified by the affidavit of the petitioner. It shall be sufficient, if the affidavit shall be upon information and belief. Such petition shall set forth the name of the parent or parents of such child, if known, and their residence; and if such child has no parent living, then the name and residence of the guardian of such child, if it has one.\n\"Upon the filing of such petition, the judge of said court shall fix the day and time for the hearing of such petition. If it appears that one or both of such parents, or guardian, if there be no parents, reside in the city, the clerk of said court shall immediately issue summons, which shall include a copy of the petition, and which shall be served on such parent, parents, or guardian, if any, if either can be found in the city, not less than two days before the time fixed for said hearing, requiring them to appear on said day and hour to show cause, if any, why such child should not be declared by said court to be a \"dependent\" or \"neglected\" child. If it appears from the petition that neither of said parents is living, or do not reside in the city and that said child has no guardian residing in said city, or in case one or both of said parents, or the guardian in case there be no parents, shall indorse on said petition a request that the child be declared a \"dependent child,\" then the summons herein provided for shall not be issued; and the court may thereupon proceed to a hearing of the case. In case neither of the parents or guardian is found, then the Court shall appoint some suitable person to represent said child in said case.\n\"Upon such hearing of such case the child shall be brought before said court; whereupon, the court shall investigate the facts, and ascertain whether the child is a \"dependent child,\" its residence, and, as far as possible, the whereabouts of its parents or near adult relatives, when and how long the child has been maintained, in whole or in part, by private or public charity, the occupation of the parents, if living, whether they are supported by the public or have abandoned the child, and to ascertain, as far as possible, if the child is found dependent, the cause thereof. The court may compel the attendance of witnesses on such examination. The city fiscal, when requested by the court, shall appear in any such examination in behalf of the petitioner. It shall be the duty of the city fiscal, upon the request of the court or any petitioner, to file a petition and to conduct any necessary proceedings in any case within the provisions of this article.\n\"In the hearing of such case, the court shall not be bound to follow the technical rules of evidence. If the said child shall be found after such hearing to be a \"dependent\" or \"neglected\" child, as defined herein, it shall be adjudged a \"dependent child;\" and an order may be entered making such disposition of the care and custody of said child as the court deems best for its moral and physical welfare. It may be turned over to the care and custody of any suitable person or any suitable institution in the city organized for the purpose of caring for \"dependent children\", and which is able and willing to care for same. If there be no such person or suitable institution, the child shall be referred to the Social Welfare Administration. And when such child is so turned over to the custody of such person or institution, such person or institution shall have the right to the custody of said child, and shall be at all times responsible for its education and maintenance, subject at all times to the order of the court.\n\"In any case where the court shall award any \"dependent\" or \"neglected\" child to the care of any individual or institution, the child, unless otherwise ordered, shall become a ward and be subject to the guardianship of the institution or individual to whose care it is committed. Any institution or individual receiving any such child under the order of the court shall be subject to visitation or inspection by any person appointed by the court for such purpose; and the court, may at any time, require from any institution or person a report containing such information as the court shall deem proper or necessary, to be fully advised as to the care, education, maintenance and moral and physical training of the child, as well as to the standing and ability of such institution or individual to care for such child. The court may change the guardianship of such child, if, at any time, it is made to appear to the court such change is to the best interests of the child. If, in the opinion of the court, the causes of the dependency of any child may be removed under such conditions or supervision for its care, protection and maintenance as may be imposed by the court, so long as it shall be for its best interests, the child may be permitted to remain in its own home and under the care and control of its own parent, parents or guardian, subject to the jurisdiction and direction of the court; and when it shall appear to the court that it is no longer to the best interests of such child to remain with such parents or guardian, the court may proceed to a final disposition of the case.\n\"In case any child is adjudged to be \"dependent\" or \"neglected\" then such parents or guardian shall thereafter have no right over or to the custody or services of said child except upon such conditions in the interest of such child as the court may impose, or where, upon proper proceedings, such child may lawfully be restored to the parents or guardian.\n\"Sec. 38-D. Proceedings in other cases. In the hearing and disposition of cases other than that covered by the preceding section, the court shall be governed by the Rules of Court and the laws properly applicable in each particular case.\n\"In cases between husband and wife, and between parent and child, however, the hearings may be held, upon petition of any party, in chamber or with the exclusion of the public. All information obtained at such hearings shall be deemed privileged and confidential and shall not be divulged without approval of the court.\n\"Sec. 38-E. Appeal from decision and order of the Court. Decisions and orders of the court shall be appealed in the same manner and subject to the same conditions as appeals from the court of first instance.\n\"Sec. 38-F. The clerk of court and subordinate employees. The Juvenile and Domestic Relations Court shall be a court of record and shall have a clerk of court and such subordinate employees as may be necessary who shall be appointed in the same manner and shall receive the same compensation as similar officials and employees of the court of first instance."}},{"id":"PH-H1235-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon the organization of the Juvenile and Domestic Relations Court, the Secretary of Justice shall cause all cases and proceedings pending before the municipal court and the court of first instance of Manila properly cognizable by the court herein created to be transferred thereto."}},{"id":"PH-H1235-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of seventy-five thousand pesos is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, for the salary and emoluments of the judge and personnel of this court as well as for the rental and other incidental expenses of the court and shall include a similar amount thereafter in the annual general appropriation acts."}},{"id":"PH-H1235-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 9, 1955"}}],"pack":"ph-p17"};
  FT["PH-H1236"] = {"id":"PH-H1236","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1402_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend the First Paragraph of Section One of Act Numbered Thirty-Five Hundred, as Amended","orig":"An Act to Amend the First Paragraph of Section One of Act Numbered Thirty-Five Hundred, as Amended"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1402","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-09","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1402_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1236-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of section one of Act Numbered Thirty-five hundred, as amended by Republic Act Numbered One hundred forty-one, is amended to read as follows:\n\"Sec. 1. The sum of ten million pesos is hereby appropriated out of any funds in the National Treasury not otherwise appropriated, to constitute a revolving fund for the construction of permanent bridges on, and for the acquisition of road rights of way and engineering surveys and investigations of, national or provincial roads in the Philippines, which shall be expended under the supervision of the Secretary of Public Works and Communications: Provided, That not less than the sum of two million pesos of said revolving fund shall be made available for the acquisition of road rights of way and for the survey and planning of roads and bridges, funds for which projects have previously been authorized by law, and which shall be repaid without interest from the construction allotments of the said projects either under the Philippine Highway Act of 1953 or under public works appropriations. Said bridges shall be declared toll bridges for a period not exceeding twenty years. Tolls shall be collected from all traffic using such bridges in accordance with rates to be fixed by a board composed of the Secretary of Public Works and Communications, as chairman, the Secretary of Finance, and the Executive Secretary, as members: Provided, However , That no toll charges shall be collected from pedestrians, whether alone or accompanying animals, or any person mounted on bicycle or an animal-drawn vehicle. The Secretary of Public Works and Communications shall issue such rules and regulations as may be necessary to implement the provisions of this Act.\""}},{"id":"PH-H1236-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 9, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1237"] = {"id":"PH-H1237","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1403_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend Section Thirteen of Republic Act Numbered Seven Hundred and Twenty, Entitled “An Act Providing for the Creation, Organization and Operation of Rural Banks, and for Other Purposes”","orig":"An Act to Amend Section Thirteen of Republic Act Numbered Seven Hundred and Twenty, Entitled “An Act Providing for the Creation, Organization and Operation of Rural Banks, and for Other Purposes”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1403","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-09","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1403_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1237-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section thirteen of Republic Act Numbered Seven hundred and twenty is hereby amended by adding a new paragraph thereof, to read as follows:\n\"In normal times, the Central Bank may rediscount against paper evidencing a loan granted by a rural bank to any of its customers which can be liquefied within a period of two hundred and seventy days.\""}},{"id":"PH-H1237-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 9, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1238"] = {"id":"PH-H1238","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1404_1955.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"对《 司法法 1948》的修改","en":"The Judiciary Act of 1948","orig":"An Act to Amend Certain Sections of Republic Act Numbered Two Hundred and Ninety-Six, Otherwise Known as “The Judiciary Act of 1948”, as Amended, and for Other Purposes"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 1404","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-09","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1404_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1238-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The second, third and ninth paragraphs of section forty-nine of Republic Act Numbered Two hundred and ninety-six, as amended, are hereby further amended to read as follows:\n\"Sec. 49. Judicial Districts. Judicial districts for Courts of First Instance in the Philippines are constituted as follows:\n\"The First Judicial District shall consist of the Provinces of Cagayan, Batanes, Isabela, and Nueva Viscaya, and the subprovince of Apayao, Mountain Province;\n\"The Second Judicial District, of the Provinces of Ilocos Norte, Ilocos Sur, Abra, City of Baguio, Mountain Province, except the subprovince of Apayao, and La Union;\n\"The Eight Judicial District, of the Province of Laguna, the City of San Pablo, the Province of Batangas, the City of Lipa, and the Provinces of Oriental Mindoro and Occidental Mindoro and Marinduque;"}},{"id":"PH-H1238-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first, second, third, sixth, seventh, eleventh, twelfth, fourteenth, fifteenth and sixteenth paragraphs of section fifty of Republic Act Numbered Two hundred and ninety-six, as amended, is further amended to read as follows:\n\"Sec. 50. Judges of First Instance for Judicial Districts. Six judges shall be commissioned for the First Judicial District. Two judges shall preside over the Courts of First Instance of Cagayan, Batanes and the Subprovince of Apayao in the Mountain Province, and shall be known as judges of the first and second branches thereof, respectively, the judge of the First branch to preside also over the Court of First Instance of the subprovince of Apayao and the judge of the second branch to preside also over the Court of First Instance of Batanes; two judges shall preside over the Court of First Instance of Isabela, and shall be known as the judges of the first and second branches thereof; and two judges shall preside over the Court of First Instance of Nueva Viscaya, to be known as the Judges of the First and Second branches thereof.\n\"Eight judges shall be commissioned for the Second Judicial District. Two judges shall preside over the Court of First Instance of Norte; two judges shall preside over the Court of First Instance of Ilocos Sur; one judge shall preside over the Court of First Instance of Abra; one judge shall preside over the Courts of First Instance of the City of Baguio and Mountain Province, except the subprovinces of Apayao, Kalinga, Bontoc and Ifugao; and two judges shall preside over the Courts of First Instance of La Union and the Subprovinces of Kalinga, Bontoc and Ifugao, and shall be known as judges of the First and Second branches thereof, respectively, the judge of the Second branch to preside also over the Courts of First Instance of the Subprovinces of Kalinga, Bontoc and Ifugao.\n\"Eight judges shall be commissioned for the Third Judicial District. Seven judges shall preside over the Court of First Instance of Pangasinan and shall be known as judges of the first, second, third, fourth, fifth, sixth and seventh branches thereof, respectively; the judges of the First and Second branches to preside over the Court of First Instance of Lingayen; the judges of the Third and Fourth branches to preside over the Court of First Instance of the City of Dagupan; the judge of the Fifth branch to preside over the Court of First Instance of Urdaneta; the judge of the Sixth branch to preside over the Court of First Instance of Tayug; and the Judge of the Seventh branch to preside over the Court of First Instance of Alaminos, Pangasinan. One judge shall preside over the Court of First Instance of Zambales.\n\"Twenty judges shall be commissioned for the Sixth Judicial District. They shall preside over the Court of First Instance of Manila and shall be known as judges of the first, second, third, fourth, fifth, sixth, seventh, eighth, ninth, tenth, eleventh, twelfth, thirteenth, fourteenth, fifteenth, sixteenth, seventeenth, eighteenth, nineteenth and twentieth branches thereof, respectively.\n\"Eleven judges shall be commissioned for the Seventh Judicial District. Seven judges shall preside over the Courts of First Instance of the Province of Rizal, Quezon City and Pasay City and shall be known as judges of the first, second, third, fourth, fifth, sixth and seventh branches thereof, respectively; three judges shall preside over the Courts of First Instance of the Province of Cavite and the Cities of Cavite and Tagaytay, and shall be known as judges of the first, second, and third branches thereof, respectively; and one judge shall preside over the Court of First Instance of Palawan.\n\"Eight judges shall be commissioned for the Eleventh Judicial District. Two judges shall preside over the Courts of First Instance of Capiz, Roxas City and Romblon and shall be known as judges of the first and second branches thereof, respectively; five judges shall preside over the Courts of First Instance of the Province of Iloilo and the City of Iloilo, and shall be known as judges of the first, second, third, fourth and fifth branches thereof, respectively; and one judge shall preside over the Court of First Instance of the Province of Antique.\n\"Seven judges shall be commissioned for the Twelfth Judicial District. Five judges shall preside over the Courts of First Instance of Occidental Negros and the City of Bacolod, and shall be known as judges of the first, second, third, fourth, and fifth branches thereof, respectively; and two judges shall preside over the Courts of First Instance of Oriental Negros, Dumaguete City and the Subprovince of Siquijor.\n\"Seven judges shall be commissioned for the Fourteenth Judicial District. Six judges shall preside over the Courts of First Instance of the Province of Cebu and the City of Cebu, and shall be known as judges of the first, second, third, fourth, fifth and sixth branches thereof, respectively; and one judge shall preside over the Court of First Instance of Bohol.\n\"Six judges shall be commissioned for the Fifteenth Judicial District. One judge shall preside over the Court of First Instance of Surigao; one judge shall preside over the Courts of First Instance of Agusan and Butuan City; two judges shall preside over the Courts of First Instance of Oriental Misamis, Cagayan de Oro and Bukidnon, and shall be known as judges of the first and second branches thereof, respectively; and two judges shall preside over the Courts of First Instance of Lanao and the Cities of Dansalan and Iligan, and shall be known as judges of the first and second branches thereof.\n\"Ten judges shall be commissioned for the Sixteenth Judicial District. Three judges shall preside over the Courts of First Instance of the Province of Davao and Davao City; two judges shall preside over the Court of First Instance of Cotabato, to be known as judges of the first and second branches thereof; one judge shall preside over the Courts of First Instance of Occidental Misamis and Ozamis City; one judge shall preside over the Court of First Instance of Zamboanga del Norte; one judge shall preside over the Court of First Instance of Zamboanga del Sur; one judge shall preside over the Courts of First Instance of Zamboanga City and Basilan City; and one judge shall preside over the Court of First Instance of Sulu."}},{"id":"PH-H1238-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section fifty-one of Republic Act Numbered Two hundred and ninety-six, as amended, is further amended to read as follows:\n\"Sec. 51. Detail of judge to another district or province. Whenever a judge stationed in any province or branch of a court in a province shall certify to the Secretary of Justice that the condition of the docket in his court is such as to require the assistance of an additional judge, or when there is any vacancy in any court or branch of a court in a province, the Secretary of Justice may, in the interest of justice, with the approval of the Supreme Court and for a period of not more than three months for each time, assign any judge of any court or province whose docket permits his temporary absence from said court, to hold sessions in the court needing such assistance or where such vacancy exists. No judge so detailed shall take cognizance of any case when any of the parties thereto objects and the objection is sustained by the Supreme Court.\n\"Whenever a judge appointed or assigned in any province or branch of a court in a province shall leave the province by transfer or assignment to another court of equal jurisdiction without having decided a case totally heard by him and which was duly argued or opportunity given for argument to the parties or their counsel, it shall be lawful for him to prepare and sign his decision in said case anywhere within the Philippines and send the same by registered mail to the clerk of the Court to be filed in the court as of the date when the same was received by the clerk, in the same manner as if the judge had been present in the court to direct the filing of the judgment: Provided, however, That if a case has been heard only in part, the Supreme Court, upon petition of any of the parties to the case and the recommendation of the respective district judge, may also authorize the judge who has partly heard the case to continue hearing and to decide said case notwithstanding his transfer or appointment to another court of equal jurisdiction."}},{"id":"PH-H1238-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The first, second, third, fourth, fifth, eighth, eleventh, twelfth, thirteenth, fifteenth, sixteenth, and seventeenth paragraphs of section fifty-two of Republic Act Numbered Two hundred and ninety-six, as amended, are further amended to read as follows:\n\"Sec. 52. Permanent stations of district judges. The permanent station of judges of the Sixth Judicial District shall be in the City of Manila.\n\"In other judicial districts, the permanent stations of the judges shall be as follows:\n\"For the First Judicial District, the judge of the first branch of the Courts of First Instance of Cagayan, Batanes and the subprovince of Apayao in the Mountain Province, shall be stationed in the Municipality of Tuguegarao, Province of Cagayan, the judge of the second branch, in the Municipality of Aparri, same province; one judge shall be stationed in the Municipality of Ilagan, Province of Isabela; one judge shall be stationed Cauayan, Isabela; and two judges, in the Municipality of Bayombong, Province of Nueva Viscaya.\n\"For the Second Judicial District, two judges shall be stationed in the Municipality of Laoag, Province of Ilocos Norte; two judges in the Municipality of Vigan, Province of Ilocos Sur; one judge in the City of Baguio; one judge, in the Municipality of Bangued, Province of Abra; and two judges, in the Municipality of San Fernando, Province of La Union.\n\"For the Third Judicial District, two judges shall be stationed in the Municipality of Lingayen, Province of Pangasinan; two judges shall be stationed in the City of Dagupan; one judge in the Municipality of Urdaneta, Province of Pangasinan; one judge, in the Municipality of Tayug, and another in the Municipality of Alaminos, same province; and one judge in the Municipality of Iba, Province of Zambales. x x x x x x x x x \"For the Seventh Judicial District, the three judges of the first, second, and sixth branches of the Court of First Instance of Rizal shall be stationed in the Municipality of Pasig, Province of Rizal; those of the third and seventh branches, in Pasay City; and those of the fourth and fifth branches in Quezon City; one judge, in the Municipality of Puerto Princesa, Province of Palawan; and three judges, in the City of Cavite. x x x x x x x x x \"For the Tenth Judicial District, three judges shall be stationed in the City of Naga, Province of Camarines Sur; two judges, in the Municipality of Legaspi, Province of Albay, one of whom shall also hold court in the Municipality of Virac, Province of Catanduanes, once a year for as long as the interest of justice requires but not exceeding six months a year; one judge, in the Municipality of Sorsogon, Province of Sorsogon; and one judge, in the Municipality of Masbate, Province of Masbate.\n\"For the Eleventh Judicial District, one judge shall be stationed in the Roxas City; one judge, in the Municipality of Calivo, Province of Capiz; one judge, in the City of Iloilo, one judge, in the Municipality of Guimbal, Province of Iloilo, one judge, in the Municipality of Santa Barbara, same province, one judge, in the Municipality of Pototan, same province, and one judge, in the Municipality of Ajuy, also of the same province; and one judge, in the Municipality of San Jose de Buenavista, Province of Antique.\n\"For the Twelfth Judicial District, five judges shall be stationed in the City of Bacolod; and two judges, in the City of Dumaguete. x x x x x x x x x \"For the Fourteenth Judicial District, six judges shall be stationed in the City of Cebu; and one judge, in the Municipality of Tagbilaran, Province of Bohol.\n\"For the Fifteenth Judicial District, one judge shall be stationed in the Municipality of Surigao, Province of Surigao; the judge of the first branch of the Courts of First Instance of Oriental Misamis, Cagayan de Oro City and Bukidnon shall be stationed in the City of Cagayan de Oro, and the judge of the second branch, in the Municipality of Malaybalay, Province of Bukidnon; the judge of the first branch of the Courts of First Instance of Lanao and the Cities of Dansalan and Iligan shall be stationed in the City of Dansalan, and the Judge of the second branch, in the City of Iligan; and one judge, in the City of Butuan.\n\"For the Sixteenth Judicial District, three judges shall be stationed in the City of Davao; the first branch of the Court of First Instance of Cotabato shall be stationed in the Municipality of Cotabato while the second branch shall be stationed in the Municipality of General Santos, Province of Cotabato; one judge in the Municipality of Oroquieta, Province of Occidental Misamis; one judge in the Municipality of Dipolog, Province of Zamboanga del Norte; one judge in the Municipality of Pagadian, Province of Zamboanga del Sur; one judge in the City of Zamboanga; and one judge in the Municipality of Jolo, Province of Sulu.\""}},{"id":"PH-H1238-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The first, tenth and eleventh subparagraphs of the second paragraph of section fifty-four of Republic Act Numbered Two hundred and Ninety-six, as amended, are further amended to read as follows:\n\"Sec. 54. Places and time for holding court. x x x x x x x x x \"First Judicial District: At Santo Domingo de Basco, Province of Batanes, on the first Tuesday of March of each year. A special term of court shall also be held once a year, in the municipalities of Ballesteros and Tuao, both of the Province of Cagayan.\n\"Fifteenth Judicial District: At Cantilan, Province of Surigao, on the first Tuesday of August of each year; a special term of court shall also be held once a year in either the Municipality of Tandag or the Municipality of Hinatuan, Province of Surigao, in the discretion of the district judge; at Mambajao, Province of Oriental Misamis, on the first Tuesday of March of each year. A special term of court shall, likewise, be held, once a year, either in the Municipality of Talisayan or in the Municipality of Gingoog, Province of Oriental Misamis, in the discretion of the district judge. The judge of the second branch of the Courts of First Instance of Oriental Misamis, Cagayan de Oro City and Bukidnon shall also hold court in Cagayan de Oro City and/or Oriental Misamis whenever the interest of justice so requires. A special term of Court shall be held at any time of the year at the Municipality of Baroy, Province of Lanao.\n\"Sixteenth Judicial District: Terms of court shall be held in the Municipality of Sindangan, Province of Zamboanga del Norte, on the dates to be fixed by the district judge; at the City of Basilan, at least four times a year on dates to be fixed by the district judge; and at Baganga and Mati, Province of Davao, terms of court shall be held at least once a year on dates to be fixed by the district judge.\""}},{"id":"PH-H1238-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"All the present district judges shall continue as such, but if any district judge is commissioned for the courts of first instance of two provinces or cities, and a separate district judge has been provided for herein for one of such courts, or one province or city is removed from the jurisdiction of his court and grouped with another province or city, and in the latter event a new province or city is grouped with the remaining province or city of the former jurisdiction of his court, such district judge shall have the option to select the court over which he shall continue to preside and notify the President of his selection with a reasonable time. If the number of branches in any court of first instance has been increased, the district judge presiding over any branch thereof in a particular place shall continue to preside over such branch notwithstanding a change in its number under the provisions of this Act, unless such district judge affected by the increase prefers to preside over the new branch, in which event he shall be given such preference to be exercised in the same manner as hereinbefore provided without the necessity of a new appointment."}},{"id":"PH-H1238-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The sum of four hundred twenty thousand pesos or so much thereof as may be necessary to implement the provisions of this Act is hereby appropriated out of any funds of the National Treasury not otherwise appropriated."}},{"id":"PH-H1238-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 9, 1955"}}],"pack":"ph-p17"};
  FT["PH-H1239"] = {"id":"PH-H1239","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1405_1955.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Prohibiting Disclosure of or Inquiry Into, Deposits with Any Banking Institution and Providing Penalty Therefor","orig":"An Act Prohibiting Disclosure of or Inquiry Into, Deposits with Any Banking Institution and Providing Penalty Therefor"},"level":"law","status":"active","topics":["tax","criminal"],"docNumber":"Republic Act No. 1405","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-09","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1405_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1239-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"It is hereby declared to be the policy of the Government to give encouragement to the people to deposit their money in banking institutions and to discourage private hoarding so that the same may be properly utilized by banks in authorized loans to assist in the economic development of the country."}},{"id":"PH-H1239-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"1 All deposits of whatever nature with banks or banking institutions in the Philippines including investments in bonds issued by the Government of the Philippines, its political subdivisions and its instrumentalities, are hereby considered as of an absolutely confidential nature and may not be examined, inquired or looked into by any person, government official, bureau or office, except upon written permission of the depositor, or in cases of impeachment, or upon order of a competent court in cases of bribery or dereliction of duty of public officials, or in cases where the money deposited or invested is the subject matter of the litigation."}},{"id":"PH-H1239-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It shall be unlawful for any official or employee of a banking institution to disclose to any person other than those mentioned in Section two hereof any information concerning said deposits."}},{"id":"PH-H1239-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All Acts or parts of Acts, Special Charters, Executive Orders, Rules and Regulations which are inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H1239-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Any violation of this law will subject offender upon conviction, to an imprisonment of not more than five years or a fine of not more than twenty thousand pesos or both, in the discretion of the court."}},{"id":"PH-H1239-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 9, 1955 Footnote 1 This Section and Section 3 were both amended by PD No. 1792 issued January 16, 1981, PD 1792 was expressly repealed by Sec 135 of R.A. No. 7653, approved June 14, 1993. The original sections 2 and 3 of R.A. No.1405 are hereby reproduced for reference, as follows; \"Sec 2 All deposits of whatever nature with banks or banking institutions in the Philippines including investments in bonds issued by the Government of the Philippines, its political subdivisions and its instrumentalities, are hereby considered as of an absolutely confidential nature and may not be examined, inquired or looked into by any person, government official, bureau or office, except upon written per-mission of the depositor, or in cases of impeachment, or upon order of a competent court in cases of bribery or dereliction of duty of public officials. or in cases where the money deposited or invested is the subject matter of the litigation,\" \"Sec. 3. It shall be unlawful for any official or employee of a banking institution to disclose to any person other than those mentioned in Section two hereof any information concerning said deposits.\""}}],"pack":"ph-p17"};
  FT["PH-H1240"] = {"id":"PH-H1240","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1406_1955.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend in Certain Particulars Commonwealth Act Numbered Three Hundred and Thirty-Eight, Known as the Charter of the City of Tagaytay","orig":"An Act to Amend in Certain Particulars Commonwealth Act Numbered Three Hundred and Thirty-Eight, Known as the Charter of the City of Tagaytay"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1406","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-09","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1406_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1240-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The second paragraph of section six of Commonwealth Act Numbered Three hundred and thirty-eight, as amended, otherwise known as the Charter of the City of Tagaytay, is further amended to read as follows:\n\"The mayor shall receive a compensation of six thousand pesos per annum. The city secretary shall receive a compensation of two thousand four hundred pesos per annum. The members of the city council, including the vice-mayor, shall each receive a per diem of ten pesos for each day of attendance at the session of the city council.\""}},{"id":"PH-H1240-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"A new section is hereby inserted between sections ten and eleven of the same Act, to be known as section ten-A, which shall read as follows:\n\"Sec. 10-A. Relations between the City of Tagaytay and the Province of Cavite. — The City of Tagaytay shall continue as part of the representative district of the Province of Cavite. The voters of the city shall be entitled to vote in the election of the elective provincial officials of the province."}},{"id":"PH-H1240-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Paragraph (g) of section eleven of the same Act, as amended, is further amended to read as follows:\n\"(g) He shall appoint, in accordance with the Civil Service Law, all employees of the office of the mayor, and all heads and assistant heads of departments, and employees and laborers of the city which may be provided for by law or ordinance, and, at any time, for cause, he may suspend any such officer or employee thus appointed for a period not exceeding ten days, which suspension may continue for a longer period if approved by the Department Head; and by and with the consent of the Department Head may discharge any such officer or employee."}},{"id":"PH-H1240-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 9, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1241"] = {"id":"PH-H1241","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1407_1955.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":null,"en":"The Philippine Overseas Shipping Act of Nineteen Hundred and Fifty-Five","orig":"An Act to be Known as “The Philippine Overseas Shipping Act of Nineteen Hundred and Fifty-Five”"},"level":"law","status":"active","topics":["trade"],"docNumber":"Republic Act No. 1407","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-09","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1407_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1241-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of policy. Shipping commands a transcendental position in the economic development and growth of a nation. One of the urgent needs of the Philippines is a well-balanced Philippine merchant marine (a) sufficient to carry the expanding international trade of the Philippines in time of peace, (b) capable of serving as a naval and military auxiliary in time of war and national emergency, (c) owned and operated under the Philippine flag by citizens of the Philippines, or by associations or corporations organized under the laws of the Philippines, at least sixty per cent of the capital of which is owned by citizens of the Philippines, and (d) composed of the best equipped, safest and most suitable types of modern vessels, and manned with trained and efficient Filipino officers and crew. To attain this objective it is hereby declared to be the policy of the Government of the Philippines: (a) to encourage and assist vessels of Philippine registry engaged in international trade; (b) to foster the development and encourage the maintenance of such a Philippine merchant marine; (c) to provide financial aid and assistance in long-range ship-building program, and at all times, to promote shipping in such other respects as may be required to attract private capital and enterprise to the shipping industry and create a healthy climate to attract private enterprise to invest in the overseas transportation; and (d) to do whatever may be necessary, from time to time, to attain these objectives.\nThe Republic of the Philippines, in common with other maritime nations, recognizes the international character of shipping in foreign trade and existing international practices in maritime transportation, and declares it to be part of its national policy to cooperate with other friendly nations in the maintenance and improvement of such practices."}},{"id":"PH-H1241-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In pursuance of the above-declared policy any citizen of the Philippines, or any association or corporation organized under the laws of the Philippines, at least sixty per cent of the capital of which is owned by citizens of the Philippines, engaged or which shall engage exclusively in the overseas shipping business, and in the construction of modern boats for overseas service shall be exempt from the payment of income tax on income derived from his or its shipping business for a period of ten years from the date of approval of this Act, provided that all those who avail themselves of the loan assistance in this Act shall invest all net profits realized during that period in the construction, purchase, or acquisition of additional vessels and equipment and/or in the improvement of its vessels and equipment."}},{"id":"PH-H1241-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is hereby appropriated out of any funds in the National Treasury not otherwise appropriated or from loans which may be contracted either locally or abroad for the purpose, by the National Development Company through an agency of the Philippine Government, for the fiscal year ending June thirty, nineteen hundred and fifty-six, and for each of the four fiscal years thereafter, the sum of twenty million pesos annually for the construction, purchase, or acquisition of ocean-going vessels for the purpose of resale, lease or charter to persons, associations or corporations referred to in section two of this Act. The fund may also be invested in loans to citizens of the Philippines or to associations or corporations organized under the laws of the Philippines, at least sixty per cent of the capital of which is owned by citizens of the Philippines, for the purpose of financing the construction, purchase, or acquisition and operation by such citizens, associations or corporations of ocean-going vessels."}},{"id":"PH-H1241-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The administration and investment of the annual sums appropriated, pursuant to section three of this Act, shall be vested in the National Development Company, which is hereby authorized and empowered to acquire ocean-going vessels for resale upon an irrevocable contract to purchase such vessels; to make from the said sums the loans referred to above; to make or cause to be made studies and investigations of the person or entity applying for the loan of the shipping service to be established; and to determine the advisability of making said loan."}},{"id":"PH-H1241-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All loans authorized under this Act shall be upon the security of a preferred mortgage on the vessel for the acquisition of which such loans are made, including its equipment, and the certificate or any other form of authorization for the operation of such vessels and the shipping service of the borrower. All said loans shall be self-liquidating within a period not to exceed twenty years and shall bear interest at the rate of not more than four and one-half per cent per annum: Provided, however , That such loans shall not exceed seventy-five per cent of the cost of the vessels: Provided, further, That such vessels shall be fully insured: Provided, finally , That no rights acquired under this Act by the vendee, lessee or charterer of the vessel shall, during the existence of the contractual agreement, be transferred or otherwise encumbered in favor of third parties without the consent of the National Development Company."}},{"id":"PH-H1241-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"All moneys representing payments of principal and interest on loans made pursuant to this Act shall be considered as special fund to be used exclusively to carry out the provisions of this Act."}},{"id":"PH-H1241-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The National Development Company is authorized and empowered to bid for and purchase at any foreclosure or other sale, or otherwise to acquire the vessels, including all other equipment, certificate or authorization, for the operation of such vessels, pledged or mortgaged to secure any loan made pursuant to this Act; to pay the purchase price and any costs and expenses incurred in connection therewith from the sums authorized in section three of this Act; to accept title to any vessel, including all its property and equipment, certificate or authorization for its operation, so purchased or acquired in the name of the Government of the Philippines; to lease or charter on bare-boat basis for an amount which, if computed annually, shall not exceed seven per cent of the total cost of such vessel and equipment and for such period as may be deemed necessary or advisable to protect the investment therein; and to sell such vessel and all its property, certificate or authorization for its operation, so acquired, upon such terms and for such consideration as the National Development Company shall determine to be reasonable. The sale of vessels shall be made only to responsible persons who are citizens of the Philippines, or associations or corporations organized under the laws of the Philippines, at least sixty per cent of the capital of which is owned by citizens of the Philippines, who agree to maintain such lines upon such terms of payment and other conditions as may be deemed just and necessary to secure and maintain the service of said lines."}},{"id":"PH-H1241-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"For the purpose of making the studies and investigations herein provided for, the National Development Company may request and utilize, with the approval of the proper heads of departments, free of charge, such services of national officers and employees and of officers and employees of any government-owned or controlled corporation as are available, and such services shall be considered to have been rendered to the departments, bureaus or offices in which they are employed."}},{"id":"PH-H1241-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The National Development Company is empowered to issue the necessary rules and regulations to carry out the provisions and purposes of this Act subject to the limitations imposed in this Act. It shall present to the Congress at the close of each fiscal year a full report of its activities under this Act."}},{"id":"PH-H1241-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The President of the Philippines may in time of war and other national emergency, take possession, absolutely or temporarily, for any naval or military purpose, of any and all vessels of Philippine registry. The Government shall pay the person whose vessels has been taken, upon ascertainment by agreement or otherwise, the fair actual value based upon normal conditions at the time of taking the interest of such person in every vessel taken absolutely, or if taken for a limited period, the fair charter value under normal conditions for such period. In case of disagreement, as to such fair value it shall be determined by appraisers, one to be appointed by the National Development Company, one by the person whose vessel has been taken, and a third by the two so appointed. The finding of such appraisers shall be final and binding upon both parties."}},{"id":"PH-H1241-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"For the purpose of this Act, an ocean-going vessel of Philippine registry is deemed to be engaged in international trade when it undertakes the carriages of goods and/or passengers from the Philippines to a foreign port, or from a foreign port to either another port or a Philippine port."}},{"id":"PH-H1241-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"All dollars required by ocean-going vessels of Philippine registry or by operators of ocean-going vessels of Philippine registry for the purchase of vessels, repair and improvement, engines, spare parts, accessories, supplies and other expenses required for the operation of the vessels in foreign ports or in the high seas, when recommended by the National Economic Council, shall be made available by the Central Bank of the Philippines or by any other agency in charge of dollar controls, subject to the rules and regulations of the Central Bank, free of exchange tax, and that all such engines, spare parts, accessories, supplies and materials needed for the repair or construction of vessels shall be exempt from the special import tax: Provided , That previous certification by the National Shipyards and Steel Corporation shall be issued to the effect that the above-mentioned vessels, repair and improvement, engines, spare parts, accessories and supplies cannot be furnished by the National Shipyards and Steel Corporation. All dollars acquired or spent by the owners of said vessels shall be properly accounted for to the Central Bank of the Philippines or to any other agency in charge of dollar controls."}},{"id":"PH-H1241-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"All laws, executive orders and regulations, or parts thereof, which are inconsistent with this Act are hereby repealed."}},{"id":"PH-H1241-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 9, 1955"}}],"pack":"ph-p17"};
  FT["PH-H1242"] = {"id":"PH-H1242","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1408_1955.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend Republic Act Numbered Twelve Hundred and Forty-Five Entitled: “An Act Amending Section Twenty-Two Hundred Nineteen and One-Half of the Revised Administrative Code and for Other Purposes,” and Other Related Provisions of the Same Code","orig":"An Act to Amend Republic Act Numbered Twelve Hundred and Forty-Five Entitled: “An Act Amending Section Twenty-Two Hundred Nineteen and One-Half of the Revised Administrative Code and for Other Purposes,” and Other Related Provisions of the Same Code"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 1408","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-09","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1408_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1242-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two thousand two hundred nineteen of the Revised Administrative Code is hereby amended to read as follows:\n\"Sec. 2219. Duties of barrio lieutenants. — The barrio lieutenant, or in his absence or inability the vice-barrio lieutenant who shall be the one who receives the highest number of votes in the election provided for in the next following section shall assist the councilor in the performance of his duties in such barrio, to which he is assigned. The councilor may, for cause, recommend for suspension or dismissal to the municipal council any of the members of the council from office.\""}},{"id":"PH-H1242-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section two thousand two hundred nineteen and one-half of the same Code as amended by Republic Act Numbered One thousand two hundred forty-five is hereby further amended to read as follows:\n\"Sec. 2219½. Barrio Council. — In each barrio there shall be organized the barrio council which shall be composed of a barrio lieutenant who shall be its chairman, and such number of vice barrio lieutenants as there are sitios within the barrio who shall assist the barrio lieutenant in the discharge of his duties, a councilman for livelihood, a councilman for education, and a councilman for health who in addition to their other duties, will look after the enforcement of laws, ordinances and resolutions pertaining to matters comprised within their respective offices and the promotion of the welfare of the barrio. In barrios where there are no sitios, there shall be one vice barrio lieutenant for every two hundred inhabitants. The barrio lieutenant and vice barrio lieutenants shall be elected at a meeting which shall be attended by at least one-third of all the residents of the barrio who are qualified voters. The election shall take place annually on the third Tuesday of January. The councilor of the barrio shall convoke and preside over the meeting. He shall appoint a board of inspectors and canvassers to conduct the election. Voting may be done either by open or secret ballot as one-half of the voters attending the election meeting may decide. Those who obtain the highest number of votes for the position for which they are candidates shall be declared elected and shall assume office immediately: Provided, However , That no person shall be elected vice barrio lieutenant unless he is a resident of the sitio.\"\n\"Every head of family who is a resident of the barrio and is twenty-one years of age or over is eligible to vote in the election, provided he has been a resident of the barrio for at least six months prior to the election.\n\"Any head of family who is a resident of the barrio and is not less than twenty-one years of age and possesses the necessary training, experience and fitness for the position may be a candidate for the barrio council.\n\"The members of the barrio council shall hold office for one year or until their successors are duly elected and qualified. But in no case can he be re-elected for more than four consecutive terms unless two years have elapsed from the expiration of his last term, in which case he shall again be eligible for election to any barrio office. They shall not receive any compensation or emolument of any kind.\n\"The barrio council shall have power to promulgate rules not inconsistent with law or ordinances of the municipal council, and subject to the approval of the latter, which shall be operative within the barrio. The council shall be responsible for the planning, budgeting and spending of funds belonging to the barrio treasury and shall have the following duties and powers:\n\"(a) To represent the barrio or portion of barrio where it is located, in cases in which such representation is not incompatible with the personality of the municipal council;\n\"(b) to hold a regular session once a month;\n\"(c) to make their own rules of procedure which shall be approved by the councilor concerned before they take effect;\n\"(d) to submit to the municipal council, through said councilor, such suggestions or recommendations as they may see fit for improvements in their place or for the welfare of the inhabitants thereof;\n\"(e) to provide for the publication by town crier or such other means as they see fit, of new laws and municipal ordinances;\n\"(f) to organize at least three times a year civil lectures tending to generalize information concerning the duties and rights of citizenship; and \"(g) to cooperate with the government for the success of measures of general interest in their respective barrios.\n\"The barrio councilmen may hold their sessions in the public school building of the barrio during hours when there are no classes, or in any house or lot in the barrio the provisional or permanent use of which may be granted to them for said purpose free of charge; and shall elect from among their number a secretary who shall prepare short minutes of the proceedings of the council and draft the recommendations or suggestions to be submitted by the same to the municipal council, in either any of the official languages of the country or in the local dialect. The barrio council shall also elect from among their number a treasurer who shall collect all fees and contributions due the barrio treasury for which he shall issue the proper receipts. He shall be the custodian of the barrio funds and shall deposit all collections with the municipal treasurer within a period of one week after receipt of such fees and contributions. He shall disburse the same in accordance with resolutions of the council, upon vouchers signed by the payee and approved by the barrio lieutenant with the approval of the municipal council and subject to availability of funds in the barrio treasury. The barrio council may provide for necessary traveling expenses for the barrio lieutenant or any member of the council.\""}},{"id":"PH-H1242-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section two thousand two hundred eighteen of the same Code as amended by Republic Act No. 733 is hereby repealed."}},{"id":"PH-H1242-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 2 of Republic Act Numbered One thousand two hundred forty-five, is hereby amended to read as follows:\n\"Sec. 2. This Act shall take effect on January first, nineteen hundred and fifty-six."}},{"id":"PH-H1242-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect on January first, nineteen hundred and fifty-six.\nApproved: September 9, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1243"] = {"id":"PH-H1243","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1409_1955.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend Certain Sections of Republic Act Numbered Twelve Hundred Sixty-Seven","orig":"An Act to Amend Certain Sections of Republic Act Numbered Twelve Hundred Sixty-Seven"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1409","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-09","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1409_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1243-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Twelve hundred sixty-seven is amended to read as follows:\n\"Sec. 1. Creation. For the enforcement of all laws and regulations governing the relation of capital and labor on all agricultural lands under any system of cultivation, there is hereby created a Court of Agrarian Relations, which shall be under the executive supervision of the Department of Justice.\""}},{"id":"PH-H1243-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section two of the same Act is amended to read as follows:\n\"Sec. 2. The Court; its Composition. The Court shall consist of an Executive Judge and eight Associate Judges with the rank of Judges of the Court of First Instance, who shall be appointed by the President of the Philippines with the consent of the Commission on Appointments of the Congress. There shall be no seniority in rank among the Associate Judges by reason of service or otherwise.\n\"The Judges may be suspended or removed in the same manner and upon the same grounds as the Judges of the Court of First Instance.\n\"The Court shall keep a record of its procedure and its orders or decisions shall be appealable directly to the Supreme Court, in accordance with the provisions of sections twelve and thirteen.\""}},{"id":"PH-H1243-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The first paragraph of section three of the same Act is amended to read as follows:\n\"Sec. 3. Qualifications of Judges; their Tenure of Office; Compensation; Oath of Office; and Vacation Period. The Executive Judge and the Associate Judges shall have the same qualifications as Judges of the Court of First Instance and, in addition, shall have engaged in the actual practice of law or shall have held a government position requiring the qualifications of a lawyer for at least ten years prior to their appointments and must be at least thirty-five years of age. They shall hold office during good behavior until they reach the age of seventy years or become incapacitated to discharge the duties of their office.\""}},{"id":"PH-H1243-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The first paragraph of section six of the same Act is amended to read as follows:\n\"Sec. 6. The Court; its Seat. The Court of Agrarian Relations, except for the Executive Judge who shall sit in Manila and the adjacent provinces and perform the administrative functions of the Court, shall have its seat in the capital of the province where each Judge is assigned. The Executive Judge shall assign at least one Judge to any province who shall hear and decide matters and/or cases brought before the Court under the provision of this Act. The decision of one Judge on any matter or case brought before the Court shall be the decision of the Court.\""}},{"id":"PH-H1243-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section seven of the same Act is amended to read as follows:\n\"Sec. 7. Jurisdiction of the Court. The Court shall have original and exclusive jurisdiction over the entire Philippines, to consider, investigate, decide, and settle all questions, matters, controversies or disputes involving all those relationships established by law which determine the varying rights of persons in the cultivation and use of agricultural land where one of the parties works the land: Provided, however , That cases pending in the Court of Industrial Relations upon approval of this Act which are within the jurisdiction of the Court of Agrarian Relations, shall be transferred to, and the proceedings therein continued in, the latter court.\""}},{"id":"PH-H1243-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The first paragraph of section ten of the same Act is amended to read as follows:\n\"Sec. 10. Rules of Procedure. The Court of Agrarian Relations shall adopt its rules of procedure and shall have such other powers as generally pertain to a court of justice: Provided, however , That in the hearing, investigation and determination of any question or controversy and in exercising any duty and power under this Act, the Court shall, in the hearing and determination of cases pending before it, not be bound strictly by the technical rules of evidence.\""}},{"id":"PH-H1243-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section twelve of the same Act is amended to read as follows:\n\"Sec. 12. Execution of Orders or Decisions. At the expiration of fifteen days from notice of the order or decision, judgment shall be entered in accordance therewith, unless during said fifteen days an aggrieved party shall move for a reconsideration of the order or decision or appeal therefrom to the Supreme Court as provided for in the next succeeding section. The institution of an appeal shall not stay the execution of the order or decision sought to be reviewed, unless for a special reason, the Court of Agrarian Relations or the Supreme Court shall order that execution be stayed, in which event the Court, in its discretion, may require the appellant to deposit with the Clerk of Court such amount as would answer for the sum involved in the order or decision or require him to give bond in such form and of such amount as to insure compliance with the order or decision in case the same is confirmed: Provided, however , That an order or decision ejecting a tenant from his landholding shall not be executed until after the decision has become final and conclusive.\n\"Any order or decision of the Court of Agrarian Relations after it has become executory may be enforced by a writ of execution or any other remedy provided by law in respect to enforcement and execution of orders, decisions, or judgments of the Courts of First Instance.\""}},{"id":"PH-H1243-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section thirteen of the same Act is amended to read as follows:\n\"Sec. 13. Review by the Supreme Court. Appeal may be taken from an order or decision of the Court of Agrarian Relations promulgated under the provisions of this Act and a review of such order or decision may be obtained in the Supreme Court by filing in such court within fifteen days from receipt of notice of such order or decision a written petition praying that it be modified or set aside in whole or in part. The review by the court shall be limited to questions of law, and findings of fact when the decision is not supported by substantial evidence.\""}},{"id":"PH-H1243-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section fourteen of the same Act is totally repealed."}},{"id":"PH-H1243-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The first paragraph of section fifteen of the same Act is amended to read as follows:\n\"Sec. 15. Personnel of the Court. Upon the recommendation of the Secretary of Justice, the President of the Philippines, with the consent of the Commission on Appointments of the Congress of the Philippines, shall appoint the Commissioners of the Court and the clerks of court. The deputy clerks of said Court and such other employees as may be required in the interest of judicial service in addition to the personnel transferred from the Tenancy Division of the Court of Industrial Relations as provided in section eleven of this Act shall be appointed by the Executive Judge, with the approval of the Court, subject to the Civil Service rules and regulations."}},{"id":"PH-H1243-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section seventeen of the same Act is amended to read as follows:\n\"Sec. 17. Abolition of the Tenancy Division of the Court of Industrial Relations. The Tenancy Division of the Court of Industrial Relations is hereby abolished and the powers and functions thereof under Commonwealth Act Numbered One hundred three, as amended, together with the appropriations of the Tenancy Division of said Court provided for under Republic Act Numbered Thirteen hundred and fifty, its personnel with Civil Service eligibility, property and equipment, are hereby transferred to the Court of Agrarian Relations: Provided, however , That the aforementioned personnel who actually rendered service after the date of approval of Republic Act Numbered Twelve hundred and sixty-seven shall be entitled to payment of their salaries for such service upon certification of the Secretary of Justice that they have rendered such services."}},{"id":"PH-H1243-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section eighteen of the same Act is amended to read as follows:\n\"Sec. 18. Appropriations. In addition to the appropriation mentioned in the preceding section, the sum of four hundred thousand pesos, or so much thereof as may be necessary, is hereby appropriated out of the unappropriated funds in the Philippine Treasury for salaries, per diem, traveling expenses, purchases of materials and equipment and other necessary sundry expenses that may be incurred in the carrying out of the provisions of this Act up to the last day of the fiscal year nineteen hundred and fifty-six. The expenses for the succeeding years shall be provided for in the current appropriations for such years."}},{"id":"PH-H1243-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 9, 1955"}}],"pack":"ph-p17"};
  FT["PH-H1244"] = {"id":"PH-H1244","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1410_1955.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Prohibit the So-Called “No-Dollar” Imports Except Under Certain Conditions","orig":"An Act to Prohibit the So-Called “No-Dollar” Imports Except Under Certain Conditions"},"level":"law","status":"active","topics":["trade"],"docNumber":"Republic Act No. 1410","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-10","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1410_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1244-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"No importation into the Philippines under the so-called \"no-dollar remittance\" shall be allowed except:\n(a) Subject to tariff and internal revenue laws, machineries, equipments, their accessories, and capital goods except raw materials imported by persons engaged in dollar-producing and dollar-saving industries as certified by the Secretary of Commerce and Industry when the said machineries, equipments, their accessories and capital goods are needed and will be used in such industries: Provided , That the repatriation of the dollar value of said capital investments shall not be allowed except when authorized by the President who shall take into consideration the level of our dollar reserves.\n(b) Commodities of a value not exceeding ten thousand pesos which are being imported for the personal use of the person or family importing them, as well as gifts sent from abroad through the post office, of an aggregate value of not more than five hundred pesos unless there is evidence of abuse in the use of this privilege, each gift to be allowed only once every six months. In case, however, of Filipino residents abroad, they may send gifts of a value not more than five hundred pesos each gift once every month, but which may be accumulated to a value not exceeding five thousand pesos.\n(c) Commodities brought from abroad by a person who is returning to the Philippines, provided they are not being brought for commercial purposes, and do not exceed five thousand pesos in value, unless there is evidence of abuse in the use of this privilege, provided this allowance will be granted only to persons returning to the Philippines once a year.\n(d) Commodities in exchange for goods exported by persons or firms making the importation on a straight barter basis when authorized by the Secretary of Commerce and Industry.\n(e) Cloths of all kinds entering the Philippines on consignment basis to be embroidered in the country and re-exported abroad after having been embroidered: Provided , That a sufficient bond be required to insure re-exportation under such rules and regulations that the Department of Commerce and Industry may promulgate.\n(f) Commodities imported pursuant to the provisions of subsections (b), (c) and (d) in excess of the amounts therein authorized shall be subject to seizure and confiscation as provided in Section 3 thereof."}},{"id":"PH-H1244-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Definition. For the purposes of this Act imports under the \"no-dollar remittance\" basis, refer to those commodities, goods or merchandise which are imported for the payment of which no foreign exchange has been allocated by the Central Bank of the Philippines."}},{"id":"PH-H1244-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Any violation of this law or any provision hereof shall subject the articles imported to seizure and confiscation by the Collector of Customs without any right of redemption or release under bond, existing laws to the contrary notwithstanding: Provided, however , That goods and commodities in transit or previously imported on a no-dollar remittance basis at the time of the approval of this Act shall not be affected by the operation of this Act."}},{"id":"PH-H1244-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Any person wilfully violating the provisions of section 1 (a) of this Act shall suffer imprisonment of not more than one year in the discretion of the court, in addition to the penalty provided for in section three hereof."}},{"id":"PH-H1244-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The implementation of the provisions of this Act shall be as it hereby is entrusted to the Department of Commerce and Industry which is hereby empowered to draft, promulgate and publish such rules and regulations as it may deem necessary for such implementation."}},{"id":"PH-H1244-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"All existing laws or parts thereof, executive orders and administrative regulations contrary to the provisions of this Act are hereby repealed: Provided , That no provision of this Act shall be interpreted to allow the importation of articles which are limited or prohibited to be imported by existing law, like virginia leaf tobacco, onions, garlic, potatoes and cabbages."}},{"id":"PH-H1244-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted, without Executive approval, September 10, 1955"}}],"pack":"ph-p17"};
  FT["PH-H1245"] = {"id":"PH-H1245","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1411_1955.html","fetchedAt":"2026-10-06","articleCount":21,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Funds for Public Works","orig":"An Act Appropriating Funds for Public Works"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1411","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-09-10","completenessNote":"全文，共 21 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1411_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1245-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Long-range Program of Capital Improvements. —For the purpose of implementing the 1955-1956 phase of the long-range program of capital improvements of the Administration as contained in Appendix A hereof the following sums or so much thereof as may be necessary are hereby appropriated out of the General Funds in the National Treasury not otherwise appropriated, for projects indicated opposite the General Revenue (GR) Finance Method, subject to the provisions hereinafter set forth, for the purposes mentioned hereunder: Provided, That in the allocation of funds for projects in this section, priority shall be given to projects already commenced or are continuing in character:\n[Itemized items omitted due to lack of space] Total (₱810,000.00) ============== Total for Miscellaneous ₱3,620,000.00 ________________ Total for Section 1 ₱36,786,200.00 =============="}},{"id":"PH-H1245-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Short-term Projects. —The following sums or so much thereof as may be necessary are hereby appropriated out of the General Funds in the National Treasury not otherwise appropriated, for short-term projects, subject to the provisions hereinafter set forth, for the purposes mentioned hereunder: Provided, That all waterworks and artesian wells projects herein authorized shall be undertaken by the National Waterworks and Sewerage Authority:\n[Itemized items omitted due to lack of space] Total for Section 2 ₱22,211,700.00"}},{"id":"PH-H1245-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"School Building Program Under Republic Act No. 836. —For the purpose of implementing Republic Act Numbered Eight hundred and thirty-six, the provision of the same as to method of financing to the contrary notwithstanding, the Secretary of Finance is hereby authorized to borrow the necessary funds to carry out the purposes of said Act under the authority granted by either Republic Numbered Two hundred and forty-five or Republic Numbered One thousand. The schedules herein itemized are approved in accordance with the provisions of Republic Act Numbered Eight hundred and thirty-six and the sums indicated thereunder are hereby appropriated:\n[Itemized items omitted due to lack of space] Total ₱96,000.00 ============== Total for Section 3 ₱20,000,000.00 =============="}},{"id":"PH-H1245-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Public Works Projects To Be Financed From Bond Issue. —The following sums or so much thereof as may be necessary are hereby appropriated from the proceeds of the sales of bonds to be issued under Republic Act Numbered One thousand, and/or from loans, that may be negotiated under existing laws, to be allocated by the President of the Philippines under the terms thereof and subject to such rules and regulations as he may prescribe:\n[Itemized items omitted due to lack of space] Total for Portworks ₱8,828,000.00 ============== Total amount authorized from Bond Issue ₱222,266,000.00 =============="}},{"id":"PH-H1245-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Apportionment of Portworks Special Fund. — The following sums or so much thereof as may be necessary are hereby apportioned and authorized to be released °ut of the construction portion of the Portworks Special Fund that have accrued under Act Numbered Three thousand five hundred and ninety-two, as amended by Commonwealth Act Numbered One hundred and thirty, not otherwise apportioned and released, for portworks projects contained in the 1955-1956 phase of the Five. year Program of Capital Improvements and indicated opposite Financing Method \"130\", to be disbursed by the Secretary of Public Works and Communications pursuant to the provisions hereinafter set forth, for the purposes mentioned hereunder:\n[Itemized items omitted due to lack of space] Total Appropriations from Portworks Fund ₱4,875,000.00 ============== SPECIAL PROVISIONS"}},{"id":"PH-H1245-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Authority to Parent-Teacher Associations to Undertake Work on School Building Projects. —Any school building project for which funds amounting to four thousand pesos or more have been allocated shall be executed through public bidding in accordance with the usual contract procedures of the Bureau of Public Works. If there are no bidders or if the project can be executed at a reasonably lower cost than the lowest bid, such project shall be executed by administration, upon the approval of the highway district engineer without the necessity of securing the usual permit from the Office of the President through the Secretary of Public Works and Communications and the General Auditing Office. Provided, That in such case, preference shall be given to members of Parent-Teachers Associations in the construction thereof, and the work shall be undertaken with the intervention of the District Highway Engineer's Office only in an advisory capacity and to acquire such data or information as to enable him to prepare a cost-performance report thereon: Provided, further, That in communities where there is adequate supply of local materials, the Parent-Teacher Associations concerned may supply such construction materials as may be found advantageous in the prosecution of the work."}},{"id":"PH-H1245-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Self-help Projects. —Projects of local character for the improvement and benefit of the rural areas are hereby declared as self-help projects if done by administration, and the wage rate of laborers employed in such projects, if and when claimed by them, shall not be less than prescribed by law for agricultural laborers who shall he given preference in employment in such projects."}},{"id":"PH-H1245-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Suspension of Work by Administration Before General Elections. —Within the period of forty-five days before every general elections, no laborer shall be employed or money spent on any project authorized under this Act, even if the money is already actually released at the beginning of such period except for:\na. Work awarded by contract before or during the period: Provided, That work undertaken under the so-called \"takay\" or \"paquiao\" system shall not be considered as work by contract.\nb. Payment for the usual costs of preparation of working drawings, specifications, bills of materials, estimates, and other procedures preparatory to actual construction, including the purchase of materials and equipment, and all incidental expenses for wages of watchmen and other laborers employed for such work in the central offices and field storehouses before the beginning of such period: Provided, That the number of such laborers shall not be increased beyond that employed when the project or projects were commenced.\nc. Emergency work necessitated by the occurence of a public calamity within the 45-day period."}},{"id":"PH-H1245-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Engineering Surcharges. —All provincial engineering surcharges on projects provided herein shall not exceed four per cent."}},{"id":"PH-H1245-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Program of Work Required Before Prosecuting Public Works. —Before prosecuting any public works the district, city or project engineer concerned shall prepare a program of work including, among other things, the total cost of materials and of the labor required, the anticipated duration of the work in men-days, the margin of contingencies above his estimates if the work is to be undertaken by administration, and in addition, an estimate of what he deems is a reasonable profit for the contractor if the work is to be undertaken by contract. In no case, however, shall this margin of contingencies be more than ten per cent of the cost of the work if undertaken by administration, or more than fifteen per cent if undertaken by contract. He shall, however, be allowed to submit a revised program of work before the completion of the project if, due to unfor-seen fluctuation in price of labor and materials or other such circumstances, it becomes evident that he cannot successfully accomplish his original program. With the exception of projects the estimated cost of which is four thousand pesos or less, under no circumstance shall the district or city engineer start work without first obtaining approval of said program from the Head of the Bureau concerned, or his representative, not lower in rank than that of a Division Engineer, and no program of work for individual projects requiring site investigation and survey and the preparation of special construction plans based thereon shall be approved unless such plans are made the basis of the program. The Auditor General or his authorized representative shall have access to the program of work or other data required in this section."}},{"id":"PH-H1245-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Purchase of Building Sites Included in Appropriations. —Any appropriation herein authorized for the construction of buildings shall be understood as including the acquisition or purchase of sites, if such acquisition or purchase is necessary for the prosecution and completion of the project."}},{"id":"PH-H1245-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Use of Public Works Funds to Pay Overdraft or Purchase of Automobiles Prohibited. —No appropriation herein authorized shall be used to pay obligations or overdraft previously incurred, and no such appropriation shall be made available for the purchase of office equipment supplies and automobiles or station wagons, neither shall such appropriations be used to pay salaries of employee except those directly connected with the work or project and as otherwise specifically provided in Title I, Sec. 1 of this Act."}},{"id":"PH-H1245-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Purchase of Materials, Equipment and Supplies for Buildings, Waterworks and Artesian Wells. —The sums necessary for the Purchase of materials, equipment and supplies, including galvanized iron or other roofing materials and other common-use building materials, for the construction of the various individual projects for buildings under Title A, for artesian wells under Title C, for waterworks systems under Title D, and particularly asphalt cement and reinforcing steel for highways under Title B of section one of this Act may be released in advance and pooled in lump sum and disbursed by the Disbursing Officer of the Bureau concerned so that wholesale purchases may be made, instead of the usual piecemeal acquisition of materials, equipment and supplies by individual projects, in order to effect a reduction in prices and avoid delays in construction resulting from the testing of every piecemeal purchase. After such wholesale purchase are made, the Head of the Bureau concerned shall distribute the materials, equipment and supplies in accordance with individual project needs; Provided, however, that in no case may an allotment for any project for any district be reduced or transferred to any project outside the district."}},{"id":"PH-H1245-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Re-adjustment of Contracts. —All constructs for the furnishing of materials, supplies and equipment, or for the construction, reconstruction, improvement or repair of any building, road, bridge, or other structure authorized in this Act, executed by the government with private persons, associations or corporations shall contain a provision that should the government at any time during the effectivity of any such contract impose or abolish any tax, customs duties, license, imposts, fee or other similar charges, or enact, amend or repeal any law affecting the number of hours of labor permissible a day or the wages or salaries to be paid to laborers, which directly increase or decrease the cost of materials, supplies and equipment or the cost of the construction work, beyond or under the amount stipulated in the contract, the said amount shall be readjusted by adding thereto or subtracting therefrom a sum equivalent to the increase or decrease represented by the tax, duty, license, impost, fee or other charge, or the difference in the cost of labor as a result of the change in the number of working hours or of the wage hours or salary."}},{"id":"PH-H1245-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Status of Five-year Capital Improvement program. —The Five-year Capital Improvement Program and Estimates annexed hereto as Appendix A is hereby an proved and shall serve as the official guide of the proper Department Head in undertaking constructions, investigation, survey and preliminary studies, including design and preparation of final estimates, plans and specifications for individual structures that may be undertaken in advance with funds authorized under sub-title a of Title I of section one and under section five of this Act; in determining special fund allocation; and for future recommendation for implementation of public works projects programmed for subsequent years thereunder."}},{"id":"PH-H1245-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Authority to Collect Tolls. —The Secretary of Public Works and Communications is empowered to authorize the collection of the necessary tolls in projects mentioned in Apendix A which are to be financed exclusively from tolls."}},{"id":"PH-H1245-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Reports. —On or before the opening day of every regular session of Congress the proper Department Head shall make a report to the Congress and to the President, in printed and bound form, which shall include a detailed statement of the work done, final estimates of cost for completion and status of each individual project, including project sites and right-of-way acquired, tolls collected, and amortizations paid on loans for projects financed thru bond issue, releases of project funds made during the fiscal year against the sums appropriated under this Act, and the unexpended balances and unreleased portions of said appropriations as of date of said report, including a statement of the extent of the relief of unemployment effected by the prosecution of public works during the year and a summary of performance by classes of public works indicating in such summary the percentages of work accomplished and work yet to be done to accomplish the program, together with his recommendations, if any, for transfers of appropriations or for program changes to be incorporated in the next Public Works Appropriation Act be enacted during the ensuing session of Congress."}},{"id":"PH-H1245-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Public Works Appropriations Under This Act Are National Disbursing Funds; Exceptions. —Any provision of existing law to the contrary notwithstanding, all funds appropriated under the provisions of this Act shall, when released, be carried in the account books of the treasurers as national disbursing funds and all the projects herein provided are classified as national projects unless such funds are appropriated specifically as aid to provinces, chartered cities and municipalities, as the case may be: Provided, That all projects in the City of Manila financed by national funds shall be undertaken by the Bureau of public Works, the provisions of any law or the city charter to the contrary notwithstanding."}},{"id":"PH-H1245-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Authority to finance projects programmed under Appropriation from General Revenue with proceeds from the issue of bonds under Republic Act No. 1000. —The President of the Philippines is authorized to modify the financial program contained in Appendix A hereof, so as to enable the Department concerned to undertake projects with the proceeds from the sales of bonds issued under Republic Act No. 1000 should sufficient amounts be unavailable in the National Treasury for the complete execution of the projects authorized under this Act to be financed from the general funds, and for such purpose the necessary sums are appropriated from said proceeds: Provided, That the project or projects for which funds shall be provided from said proceeds are certified to by the National Economic Council as self-liquidating and/or revenue-producing or as a project or projects sufficiently studied as among those which will be revenue-producing in a few years."}},{"id":"PH-H1245-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Release of Project Funds. —Upon request of the Department Head concerned, the sums appropriated under sections one and two hereof shall be released by the Commissioner of the Budget, who is hereby authorized to give Priority to any project provided for in this Act over authorized appropriations other than for the ordinary operation of the National Government: Provided, That in releasing funds and in initiating public works projects under this Act, not more than sixty per centum of the amount appropriated under section one shall be released until after the entire amount appropriated under section two hereof shall have been released, except the amount appearing under Title I, section one, or so much thereof as the Secretary of Public Works and Communications may determine, which shall have precedence over all other releases, Provided further, That when a project is not divisible, and release of funds by quarter will operate to delay unnecessarily the execution of the work, the funds appropriated for such projects shall be released in whole the provisions of the Republic Act No. 992 and similar provisions of Republic Act No. 1150 and other appropriation Acts to the contrary notwithstanding."}},{"id":"PH-H1245-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted, without Executive approval, September 10, 1955."}}],"pack":"ph-p17"};
  FT["PH-H1246"] = {"id":"PH-H1246","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1412_1956.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Transmission Free of Charge Within the Philippines of Mail Matter and Telegrams of the Office of the President of the Philippines","orig":"An Act Providing for the Transmission Free of Charge Within the Philippines of Mail Matter and Telegrams of the Office of the President of the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1412","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-03-28","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1412_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1246-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"All mail matter and telegrams of the President of the Philippines, addressed for delivery within the Philippines, shall be received, transmitted and delivered free of charge: Provided, That each such mail matter when addressed to persons or offices other than government officers or offices shall not exceed one hundred and twenty grams in weight."}},{"id":"PH-H1246-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The envelope or wrapper of such mail matter shall bear on the left upper corner the words \"President of the Philippines\" and on the right upper corner the words \"Penalty for private or unauthorized use to avoid payment of postage, five hundred pesos\"."}},{"id":"PH-H1246-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Any person who shall violate the provisions of this Act shall be punished by a fine of not more than five hundred pesos."}},{"id":"PH-H1246-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 28, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1247"] = {"id":"PH-H1247","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1413_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Two Hundred Thousand Pesos for the Employment of Temporary Personnel in the Bureau of Posts During the Period from February to June, Nineteen Hundred Fifty-Six","orig":"An Act Appropriating the Sum of Two Hundred Thousand Pesos for the Employment of Temporary Personnel in the Bureau of Posts During the Period from February to June, Nineteen Hundred Fifty-Six"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 1413","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-04-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1413_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1247-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of two hundred thousand pesos is hereby appropriated, out of any funds in the National Treasury of the Philippines not otherwise appropriated, for the employment of temporary personnel of the Bureau of Posts in Manila and in the different post offices in the Philippines during the period from February to June, nineteen hundred fifty-six."}},{"id":"PH-H1247-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect as of February 1, 1956.\nApproved: April 21, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1248"] = {"id":"PH-H1248","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1414_1956.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Create the Province of Aklan","orig":"An Act to Create the Province of Aklan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1414","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-04-25","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1414_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1248-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Province of Aklan is hereby created to consist of the municipalities of Altavas, Balete, Batan, Banga, Buruanga, Ibajay, Kalibo, Lezo, Libacao, Madalag, Malay, Makato, Malinao, Nabas, New Washington, Numancia, and Tangalan, heretofore, being and forming a part of the present Province of Kalibo."}},{"id":"PH-H1248-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Capital of the Province of Aklan shall be the Municipality of Kalibo."}},{"id":"PH-H1248-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Except as hereinafter provided, all provisions of law now or hereafter applicable to the regular provinces shall be applicable to the Province of Aklan. The said Province of Aklan shall be within the jurisdiction of the Eleventh Judicial District."}},{"id":"PH-H1248-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Upon the effectivity of this Act, the elective provincial officers of the Province of Aklan shall be appointed by the President of the Philippines with the advice and consent of the Commission on Appointments, and shall hold office until their successors shall have been duly elected and shall have qualified at the next general elections."}},{"id":"PH-H1248-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Province of Aklan shall have one Representative District: Provided, However , That the incumbent Representatives for each respective District of the Province of Capiz shall continue to serve their terms of office until the next general elections for national officials."}},{"id":"PH-H1248-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"For purposes of this Act, the Second Representative District of Capiz shall thereafter be constituted by the municipalities of Tapaz, Sigma, Mambusao, Jamindan and Sapian."}},{"id":"PH-H1248-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The funds and properties of all kinds to be assigned to the Provinces of Aklan and Capiz upon execution of the provisions of this Act shall be distributed equitably between two provinces, in such manner as the Auditor General may recommend and the President of the Philippines may approve."}},{"id":"PH-H1248-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect on such date as may, by proclamation, be set by the President of the Philippines.\nApproved: April 25, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1249"] = {"id":"PH-H1249","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1415_1956.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Municipality of Bacolod in the Province of Lanao","orig":"An Act Creating the Municipality of Bacolod in the Province of Lanao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1415","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-05-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1415_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1249-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Bacolod, Rupagan, Minaolon, Dimologan, Binuni, Liangan West, Esperanza, Cahayag, Camp One, Camp Three, Mati East and West, Pagawayan, Babalaya-Matabaogan, Dilabayan and Barogohan East are separated from the municipality of Kolambugan, Province of Lanao, and constituted into a new and regular municipality to be known as the Municipality of Bacolod in the same province, with the seat of government at the poblacion of Bacolod."}},{"id":"PH-H1249-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality shall be appointed by the President of the Philippines and shall hold office until their successors shall have been elected and shall have duly qualified."}},{"id":"PH-H1249-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 10, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1250"] = {"id":"PH-H1250","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1416_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Section Nine of Republic Act Numbered Two Hundred Ninety-One so as to Confer the Grades of Lieutenant General and Major General Upon the Officers Holding the Positions of Chief of Staff and Vice-Chief of Staff, Respectively","orig":"An Act Amending Section Nine of Republic Act Numbered Two Hundred Ninety-One so as to Confer the Grades of Lieutenant General and Major General Upon the Officers Holding the Positions of Chief of Staff and Vice-Chief of Staff, Respectively"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1416","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-05-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1416_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1250-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Paragraph (a) of section nine of Republic Act Numbered Two hundred and ninety-one is hereby amended to read as follows:\n\"Sec. 9. Promotion to grade of major general and lieutenant general. — (a) The grade of lieutenant general in the active list shall be conferred only upon the officer appointed by the President, with the consent of the Commission on Appointments, to the office of Chief of Staff of the Armed Forces of the Philippines. The grade of the major general in the active list shall be conferred only upon the officer appointed by the President, with the consent of the Commission on Appointments, to the Office of Vice Chief of Staff of the Armed Forces of the Philippines."}},{"id":"PH-H1250-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 14, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1251"] = {"id":"PH-H1251","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1417_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of Longos, Province of Laguna, to Municipality of Kalayaan","orig":"An Act Changing the Name of the Municipality of Longos, Province of Laguna, to Municipality of Kalayaan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1417","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-05-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1417_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1251-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of Longos, Province of Laguna, is changed to Municipality of Kalayaan."}},{"id":"PH-H1251-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 17, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1252"] = {"id":"PH-H1252","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1418_1956.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Transfer to the Municipality of Talisay, Province of Batangas, its Former Barrios of Caloocan and Birinayan Which were Annexed to the City of Tagaytay","orig":"An Act to Transfer to the Municipality of Talisay, Province of Batangas, its Former Barrios of Caloocan and Birinayan Which were Annexed to the City of Tagaytay"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1418","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-07","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1418_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1252-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The former barrios of Caloocan and Birinayan of the Municipality of Talisay, Province of Batangas, which were annexed to the City of Tagaytay, are hereby separated from the latter city and transferred to the said Municipality of Talisay."}},{"id":"PH-H1252-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The portion of Executive Order Numbered Three hundred and thirty-six, dated April first, nineteen hundred and forty-one, relating to the transfer of the said barrios of Caloocan and Birinayan to the City of Tagaytay, is hereby repealed."}},{"id":"PH-H1252-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 7, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1253"] = {"id":"PH-H1253","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1419_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipal District of Watu, Province of Lanao, to Municipal District of Balindong","orig":"An Act Changing the Name of the Municipal District of Watu, Province of Lanao, to Municipal District of Balindong"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1419","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1419_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1253-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipal District of Watu, Province of Lanao, is changed to Municipal District of Balindong."}},{"id":"PH-H1253-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1254"] = {"id":"PH-H1254","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1420_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipal District of Maguing, Province of Lanao, to Municipal District of Lumba Bayabao","orig":"An Act Changing the Name of the Municipal District of Maguing, Province of Lanao, to Municipal District of Lumba Bayabao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1420","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1420_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1254-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipal District of Maguing, Province of Lanao, is changed to Municipal District of Lumba Bayabao."}},{"id":"PH-H1254-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1255"] = {"id":"PH-H1255","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1421_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipal District of Gata, Province of Lanao, to Municipal District of Poona Bayabao","orig":"An Act Changing the Name of the Municipal District of Gata, Province of Lanao, to Municipal District of Poona Bayabao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1421","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1421_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1255-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipal District of Gata, Province of Lanao, is changed to Municipal District of Poona Bayabao."}},{"id":"PH-H1255-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1256"] = {"id":"PH-H1256","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1422_1956.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Change the Name of the Kabankalan Elementary School, Situated at Kabankalan, Negros Occidental, to Esteban R. Abada Memorial School","orig":"An Act to Change the Name of the Kabankalan Elementary School, Situated at Kabankalan, Negros Occidental, to Esteban R. Abada Memorial School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1422","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1422_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1256-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Kabankalan Elementary School situated at Kabankalan, Negros Occidental, is hereby named and to be known henceforth as the Esteban R. Abada Memorial School."}},{"id":"PH-H1256-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Director of Public Schools shall effect the change immediately upon the approval in this Act."}},{"id":"PH-H1256-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1257"] = {"id":"PH-H1257","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1423_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Sabang Elementary School in the Barrio of Sabang, City of Lipa, to G.B. Lontok Memorial Elementary School","orig":"An Act Changing the Name of the Sabang Elementary School in the Barrio of Sabang, City of Lipa, to G.B. Lontok Memorial Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1423","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1423_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1257-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Sabang Elementary School in the barrio of Sabang, City of Lipa, is changed to G.B. Lontok Memorial Elementary School."}},{"id":"PH-H1257-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1258"] = {"id":"PH-H1258","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1424_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"The Charter of the City of Bacolod","orig":"An Act Further Amending Section Seven of Commonwealth Act Numbered Three Hundred Twenty-Six, Otherwise Known as “The Charter of the City of Bacolod”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1424","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1424_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1258-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Paragraph one of section seven of Commonwealth Act Numbered Three hundred twenty-six, as amended by Republic Act Numbered Three hundred, is further amended to read as follows:\n\"Sec. 7. Relations between the City of Bacolod and the Provincial Government of Negros Occidental. -For election purposes, the City of Bacolod unless otherwise provided shall continue as part of the Second Congressional District of the Province of Negros Occidental. The voters of the City of Bacolod shall take part in the election of provincial officers of Negros Occidental, but the latter shall have no jurisdiction over the City of Bacolod and the officers of the same.\""}},{"id":"PH-H1258-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 12, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1259"] = {"id":"PH-H1259","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1425_1956.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Include in the Curricula of All Public and Private Schools, Colleges and Universities Courses on the Life, Works and Writings of Jose Rizal, Particularly His Novels Noli Me Tangere and El Filibusterismo, Authorizing the Printing and Distribution Thereof, and for Other Purposes","orig":"An Act to Include in the Curricula of All Public and Private Schools, Colleges and Universities Courses on the Life, Works and Writings of Jose Rizal, Particularly His Novels Noli Me Tangere and El Filibusterismo, Authorizing the Printing and Distribution Thereof, and for Other Purposes"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1425","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-12","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1425_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1259-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Courses on the life, works and writings of Jose Rizal, particularly his novel Noli Me Tangere and El Filibusterismo, shall be included in the curricula of all schools, colleges and universities, public or private: Provided, That in the collegiate courses, the original or unexpurgated editions of the Noli Me Tangere and El Filibusterismo of their English translation shall be used as basic texts.\nThe Board of National Education is hereby authorized and directed to adopt forthwith measures to implement and carry out the provisions of this Section, including the writing and printing of appropriate primers, readers and textbooks. The Board shall, within sixty (60) days from the effectivity of this Act, promulgate rules and regulations, including those of disciplinary nature, to carry out and enforce the provisions of this Act. The Board shall promulgate rules and regulations providing for the exemption of students for reasons of religious belief stated in a sworn written statement, from the requirement of the provision contained in the second part of the first paragraph of this section; but not from taking the course provided for in the first part of said paragraph. Said rules and regulations shall take effect thirty (30) days after their publication in the Official Gazette."}},{"id":"PH-H1259-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"It shall be obligatory on all schools, colleges and universities to keep in their libraries an adequate number of copies of the original and unexpurgated editions of the Noli Me Tangere and El Filibusterismo, as well as of Rizal’s other works and biography. The said unexpurgated editions of the Noli Me Tangere and El Filibusterismo or their translations in English as well as other writings of Rizal shall be included in the list of approved books for required reading in all public or private schools, colleges and universities.\nThe Board of National Education shall determine the adequacy of the number of books, depending upon the enrollment of the school, college or university."}},{"id":"PH-H1259-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Board of National Education shall cause the translation of the Noli Me Tangere and El Filibusterismo, as well as other writings of Jose Rizal into English, Tagalog and the principal Philippine dialects; cause them to be printed in cheap, popular editions; and cause them to be distributed, free of charge, to persons desiring to read them, through the Purok organizations and Barrio Councils throughout the country."}},{"id":"PH-H1259-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Nothing in this Act shall be construed as amendment or repealing section nine hundred twenty-seven of the Administrative Code, prohibiting the discussion of religious doctrines by public school teachers and other person engaged in any public school."}},{"id":"PH-H1259-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The sum of three hundred thousand pesos is hereby authorized to be appropriated out of any fund not otherwise appropriated in the National Treasury to carry out the purposes of this Act."}},{"id":"PH-H1259-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 12, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1260"] = {"id":"PH-H1260","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1426_1956.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting Mr. Enrique Zobel, of Forbes Park, Makati, Rizal, a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land-Based and Land-Mobiled Radio Stations and Private Aeronautical Land Stations for Communication with Grantee’s Own Plane or Planes for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting Mr. Enrique Zobel, of Forbes Park, Makati, Rizal, a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land-Based and Land-Mobiled Radio Stations and Private Aeronautical Land Stations for Communication with Grantee’s Own Plane or Planes for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1426","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-12","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1426_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1260-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Enrique Zobel, of Forbes Park, Makati, Rizal, his successors or assigns, a temporary permit to construct, maintain and operate in the Philippines, at such places as the said grantee may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point and land-based and land-mobile radio stations and private aeronautical land stations for communication with grantee’s own plane or planes for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H1260-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction or installation of said stations is begun within one year from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H1260-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, his successors, or assigns, shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, maintain and operate private fixed point-to-point and land-based and land-mobile radio stations and private aeronautical land stations for communication with grantee’s own plane or planes in such places within the Philippines as the interest of the grantee’s agricultural or industrial activities justify."}},{"id":"PH-H1260-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H1260-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, his successors or assigns, shall so construct and operate his radio stations in such manner that the same will not interfere with the operations of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1260-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, his successors or assigns, shall hold the national, provincial, city or municipal government of the Philippines harmless against all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of his radio stations."}},{"id":"PH-H1260-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, his successors or assigns, is authorized to operate his private fixed point-to-point and land-based and land-mobile radio stations, and private aeronautical land stations in the medium frequency, high frequency, and very high frequency that may be assigned to him by the Secretary of Public Works and Communications."}},{"id":"PH-H1260-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in times of war, insurrection, public peril, calamity or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use or possession thereof by any department of the Government upon just compensation."}},{"id":"PH-H1260-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This temporary permit shall not be transferred or in any way alienated without the previous consent of Congress and shall be subject to amendments, alterations, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege therein provided for."}},{"id":"PH-H1260-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 12, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1261"] = {"id":"PH-H1261","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1427_1956.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Funds to Carry Out the Purposes of the Jose Rizal National Centennial Commission Created by Executive Order Numbered Fifty-Two, Dated August Ten, Nineteen Hundred and Fifty-Four","orig":"An Act Appropriating Funds to Carry Out the Purposes of the Jose Rizal National Centennial Commission Created by Executive Order Numbered Fifty-Two, Dated August Ten, Nineteen Hundred and Fifty-Four"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1427","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-12","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1427_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1261-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of two million pesos is hereby appropriated out of the general funds in the National Treasury, not otherwise appropriated, to be treated as a revolving fund for the celebration of the First Centenary of the birth of Jose Rizal, including the payment of salaries of personnel, traveling expenses of the same, purchase of equipment, publication of the unexpurgated works of Jose Rizal and such work of others about him as are considered necessary in the proper understanding of the meaning of his life and labors, and other sundry expenses: Provided, That the amount shall be disbursed as follows: Six hundred thousand during the fiscal year 1956-1957; Four hundred thousand during the fiscal year 1957-1958; Five hundred thousand during the fiscal year 1958-1959; and Five hundred thousand during the fiscal year 1959-1960: Provided, further, That the overhead expenses in any given year shall not exceed twelve per centum of the appropriation for that year."}},{"id":"PH-H1261-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Commission shall undertake the construction of a National Cultural Shrine to be dedicated to Jose Rizal, such shrine to consist of a national theater, a national museum and a national library to be erected preferably at a single site. All existing and applicable laws, executive orders, plans, projects and appropriations for a national theater, a national museum and a national library are hereby amended so that the said theater, museum and library shall become parts of the National Cultural Shrine herein provided, under the jurisdiction of the Commission. This provision shall be without prejudice to the construction of other memorials dedicated to Jose Rizal.\nThe Commission is hereby authorized and directed to organize and undertake a national fund campaign for the purpose of raising funds from private sources, in order to afford the people an opportunity to participate in financing the construction of the shrine and other memorials herein provided for."}},{"id":"PH-H1261-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The books and the publications, stamps, medals etc. issued or published by the Commission shall be sold without profit to the public, and the proceeds therefrom shall be made immediately available to the Commission for which it was created and organized until the termination of its work."}},{"id":"PH-H1261-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Commission which shall be composed of:\nThe Secretary of Education ..........................\nChairman\nThe Secretary of Finance ..........................\nCo-Vice Chairman\nThe Supreme Commander of the Order of the Knights of Rizal ..........................\nCo-Vice Chairman\nThe Chairman of the Committee on Education of the Senate ..........................\nMember\nThe Chairman of the Committee on Education of the House of Representatives ..........................\nMember\nThe"}}],"pack":"ph-p17"};
  FT["PH-H1262"] = {"id":"PH-H1262","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1428_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Create the Municipality of Lapinig in the Province of Samar","orig":"An Act to Create the Municipality of Lapinig in the Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1428","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1428_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1262-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created in the Province of Samara a municipality to be known as the Municipality of Lapinig, which shall consist of portions of the municipalities of Gamay and Oras and the Municipal District of Jipapad, all in the Province of Samar, more particularly described and bounded as follows:\nOn the north, northwest, and west by a straight line running southwesterly from a point on the shore line half way between the center of the mouth of Gamay River and the poblacion of the barrio of Gamay River with the trail connecting the barrios of Cagamotan and Bagon de Camay, thence southeasterly to appoint one-half kilometer west of the poblacion of the barrio of Can Maria;\nOn the southwest by a straight imaginary line running from the said point one-half kilometer west of Can Maria to a point on Catumsan River southwest of the poblacion of barrio Catumsan;\nOn the southeast by the course of the Catumsan River downstream to the mouth of the said river which is at the Helm Harbor; and On the northeast by the limits of municipal water which Lapinig shall have pursuant to section twenty-three hundred twenty-one of the Revised Administrative Code.\nThe Municipality of Lapinig shall contain the barrios of Cagamotan, Potong, Pio del Pilar, Canomanio, Look, Lapinig, Can Maria and Catumsan, and the sitios of Cahagwayan, Palanas and Mabini, and shall have its seat of government at the barrio of Lapinig.\nThe municipalities of Gamay and Oras and the Municipal District of Jipapad shall have their present territories minus the respective portion thereof included in the Municipality of Lapinig.\nThe first mayor, vice-mayor and councilors of the Municipality of Lapinig shall be appointed by the President of the Philippines and shall hold office until their successors shall have been elected in the next regular election for provincial and municipal officials and shall have qualified."}},{"id":"PH-H1262-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1263"] = {"id":"PH-H1263","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1429_1956.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Convert the Alicia Agricultural and Fishery School in the Province of Catanduanes into a National Agricultural and Industrial School to be Known as the Catanduanes Agricultural and Industrial School, Authorizing the Appropriation of Two Hundred Thousand Pesos for the Purpose","orig":"An Act to Convert the Alicia Agricultural and Fishery School in the Province of Catanduanes into a National Agricultural and Industrial School to be Known as the Catanduanes Agricultural and Industrial School, Authorizing the Appropriation of Two Hundred Thousand Pesos for the Purpose"},"level":"law","status":"active","topics":["environment","education"],"docNumber":"Republic Act No. 1429","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1429_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1263-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Alicia Agricultural and Fishery School situated in the Municipality of Panganiban, Province of Catanduanes, is hereby converted into a national agricultural and industrial school to be known as the \"Catanduanes Agricultural and Industrial School.\"\nThe course of instruction shall include, in addition to those now offered, other industrial courses, and the Secretary of Education is hereby empowered to reorganize said school accordingly."}},{"id":"PH-H1263-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos for the conversion of said school, as provided in this Act, and its operation and maintenance for the first school year after the approval of this Act is authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated. Thereafter, the necessary appropriation for its operation shall be included in the Annual General Appropriation Act."}},{"id":"PH-H1263-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1264"] = {"id":"PH-H1264","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1430_1956.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend Section Eleven Hundred Fifty-One of the Administrative Code, as Amended, by Adding Batangas, Province of Batangas, as Port of Entry, and Authorizing the Appropriation of Funds Therefor","orig":"An Act to Amend Section Eleven Hundred Fifty-One of the Administrative Code, as Amended, by Adding Batangas, Province of Batangas, as Port of Entry, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 1430","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1430_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1264-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eleven hundred fifty-one of the Administrative Code, as amended by Republic Act Numbered Eleven hundred and seventy-three, is further amended to read as follows:\n\"Sec. 1151. Collection districts and ports of entry thereof. -For administrative purposes, the Philippines shall be divided into nineteen collection districts, the respective limits of which may be changed from time to time in the discretion of the Insular Collector of Customs, but the Province of Pangasinan shall belong to the district of Pangasinan, with Sual as its port of entry, and the Province of Quezon to the district of Quezon, with Hondagua as its port of entry. The principal ports of entry for the respective collection districts shall be Manila, Sual, Tabaco, Cebu, Pulupandan, Hondagua, Iloilo, Davao, Legaspi, Zamboanga, Jolo, Aparri, Jose Panganiban, Cagayan, Tacloban, San Fernando, Hinigaran, Dumaguete City, and Batangas.\""}},{"id":"PH-H1264-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred fifty thousand pesos is authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment and operation of the customs service at the port of Batangas, Province of Batangas."}},{"id":"PH-H1264-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1265"] = {"id":"PH-H1265","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1431_1956.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting to Rosiano Rodano a Franchise for an Electric Light, Heat and Power System in the Municipality of Malaybalay, Province of Bukidnon","orig":"An Act Granting to Rosiano Rodano a Franchise for an Electric Light, Heat and Power System in the Municipality of Malaybalay, Province of Bukidnon"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1431","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1431_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1265-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Rosiano Rodano, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the limits of the Municipality of Malaybalay, Province of Bukidnon."}},{"id":"PH-H1265-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee is hereby authorized to organize a corporation to which he is empowered to sell or assign this franchise, but thereafter the said corporation shall neither lease, transfer, grant the usufruct of, sell or assign this franchise and the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial; or legal entity, nor merge with any other company or corporation organized for the same purpose without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or which may hereafter be enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred, or assigned shall be subject to all the conditions, terms, restrictions and limitations of this franchise, as fully and completely and to the same extent as if the franchise has been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1265-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1265-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the plant and enterprise herein authorized, the grantee shall surrender his franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1265-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon it approval.\nApproved: June 14, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1266"] = {"id":"PH-H1266","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1432_1956.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting to the Farmers’ Cooperative Marketing Association a Franchise to Install, Operate, and Maintain an Electric Light, Heat, and Power System in the Municipality of Solano, Province of Nueva Vizcaya","orig":"An Act Granting to the Farmers’ Cooperative Marketing Association a Franchise to Install, Operate, and Maintain an Electric Light, Heat, and Power System in the Municipality of Solano, Province of Nueva Vizcaya"},"level":"law","status":"active","topics":["investment","company","environment"],"docNumber":"Republic Act No. 1432","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1432_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1266-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to the Farmers’ Cooperative Marketing Association, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat, and/or power for sale within the Municipality of Solano, Province of Nueva Vizcaya."}},{"id":"PH-H1266-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1266-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that, in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1266-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1267"] = {"id":"PH-H1267","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1433_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend Items Nineteen and Twenty, aa. La Union, Paragraph I, Title B, of Section One of Republic Act Numbered One Thousand Two Hundred","orig":"An Act to Amend Items Nineteen and Twenty, aa. La Union, Paragraph I, Title B, of Section One of Republic Act Numbered One Thousand Two Hundred"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 1433","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1433_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1267-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Items nineteen and twenty, aa. La Union, paragraph I, title B, of section one Republic Act Numbered One thousand two hundred, are amended to read as follows:\n\"(19) Leones-Macalva Tubao-Agoo-Completion ₱8,000.00 \"(20) Sta. Teresa Road, Tubao-Completion 5,000.00\""}},{"id":"PH-H1267-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1268"] = {"id":"PH-H1268","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1434_1956.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Establish the Samar Institute of Technology","orig":"An Act to Establish the Samar Institute of Technology"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1434","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1434_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1268-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established in the Municipality of Catarman, Province of Samar, a vocational college to be known as the Samar Institute of Technology which shall offer not only elementary, secondary general, secondary vocational and normal courses of instruction but also collegiate agricultural and industrial courses leading to bachelors’ degrees. It shall also offer opportunities for manual labor as assistance to self-supporting students."}},{"id":"PH-H1268-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The head of the Institute shall be known as the President of the Samar Institute of Technology. He shall be appointed by the President of the Philippines upon the recommendation of the Board of Trustees of the Institute. The powers and duties of the President of the Institute, in addition to those specifically provided in this Act, shall be those usually pertaining to the office of the president of a college or university."}},{"id":"PH-H1268-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The governing body of the Institute shall be the Board of Trustees of the Samar Institute of Technology. The said Board shall be composed of the Secretary of Education, who shall be the chairman, the Chairman of the Committee on Education of the House of Representatives, the Director of Public Schools, the President of the Institute, and a prominent resident of Samar to be designated by the President of the Philippines.\nThe trustees of the Institute shall serve without compensation other than actual and necessary expenses incurred either in attendance upon meetings of the Board or upon other official business authorized by resolution thereof."}},{"id":"PH-H1268-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Board of Trustees shall have the following powers and duties, in addition to its general powers of administration:\n(a) To receive and appropriate such sums as may be provided by law for the support of the Institute;\n(b) To confer certificates, diplomas or degrees upon successful candidates for graduation;\n(c) To appoint, on the recommendation of the President of the Institute, teachers, principals, supervisors, instructors, professors, lecturers, and other employees of the Institute; to fix their compensation, hours of service and such other duties and conditions as it may deem proper; to grant them, in its discretion, leave of absence under such regulations as it may promulgate, any provision of law to the contrary notwithstanding; and to remove them for cause after due investigation and hearing;\n(d) To approve the curricula and rules of discipline drawn up by the Institute Council as hereinafter provided;\n(e) To fix the tuition fees required of students, as well as matriculation fees, graduation fees and fees for laboratory courses, and all special fees, and to remit the same in special cases;\n(f) To provide fellowships for faculty members and scholarships to students showing evidence of special merit;\n(g) To provide rules for its own government, and to promulgate for the government of the Institute such general ordinances and regulations, not contrary to law, as are necessary;\n(h) To receive in trust legacies, gifts and donations of real and personal property of all kinds and to administer the same and other properties of the Institute for the benefit of the Institute or for aid to any student, in accordance with the directions and instructions of the donor, and, in default thereof, in such manner as the Board of Trustees may in its discretion determine;\n(i) To mortgage, lease, pledge, or otherwise encumber the whole or any portion of the real or personal properties of the Institute."}},{"id":"PH-H1268-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"A quorum of the Board of Trustees shall consist of a majority of all the members. All process against the Board of Trustees shall be served on the President or secretary thereof."}},{"id":"PH-H1268-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"On or before the fifteenth day of June of each year, the Board of Trustees shall file with the President of the Philippines a detailed report, setting forth the progress, conditions and needs of the Institute."}},{"id":"PH-H1268-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"There shall be an Institute Council consisting of the President of the Institute and of all instructors and professors of the Institute. The Council shall have the power to prescribe the curricula and rules of discipline, subject to the approval of the Board of Trustees. It shall fix the requirements for admission to the Institute, as well as for graduation and the receiving of a degree. The Council alone shall have the power to recommend students or others to be recipients of degrees. Through its President or committee, it shall have disciplinary power over the students within the limits prescribed by the rules of discipline approved by the Board of Trustees."}},{"id":"PH-H1268-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The Body of teachers, principals, supervisors, instructors and professors of the Institute shall constitute the faculty of the Institute, with the President of the Institute as the presiding officer. In the appointment of professors or instructors of the Institute, no religious test shall be applied, nor shall the religious opinions or affiliations of the faculty of the Institute be made a matter of examination or inquiry: Provided, However , That no instructor or professor in the Institute shall inculcate sectarian tenets in any of the teachings, nor attempt either directly or indirectly, under penalty of dismissal by the Board of Trustees, to influence students or attempts at the Institute for or against any particular church or religious sect."}},{"id":"PH-H1268-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Professors and other regular instructors in the Institute shall be exempt as such from any civil service examinations or regulations as a requisite for appointment."}},{"id":"PH-H1268-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"There shall be a secretary of the Institute, to be appointed by the Board of Trustees. He shall be the secretary of such Board and also of the Institute, and shall keep such records of the Institute as may be designated by the Board."}},{"id":"PH-H1268-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The Catarman Agricultural High School is abolished and all its personnel, unexpended appropriations, properties and other assets are transferred to the Samar Institute of Technology."}},{"id":"PH-H1268-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The sum of fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purposes of this Act."}},{"id":"PH-H1268-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1269"] = {"id":"PH-H1269","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1435_1956.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Provide Means for Increasing the Highway Special Fund","orig":"An Act to Provide Means for Increasing the Highway Special Fund"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1435","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1435_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1269-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one hundred and forty-two of the National Internal Revenue Code, as amended, is further amended to read as follows:\n\"Sec. 142. Specific Tax on manufactured oils and other fuels.— On refined and manufactured mineral oils and motor fuels, there shall be collected the following taxes:\n\"(a) Kerosene or petroleum, per liter of volume capacity, two and one-half centavos;\n\"(b) Lubricating oils, per liter of volume capacity, seven centavos;\n\"(c) Naptha, gasoline, and all other similar products of distillation, per liter of volume capacity, eight centavos; and \"(d) On denatured alcohol to be used for motive power, per liter of volume capacity, one centavo: Provided, That if the denatured alcohol is mixed with gasoline, the specific tax on which has already been paid, only the alcohol content shall be subject to the tax herein prescribed. For the purpose of this subsection, the removal of denatured alcohol of not less than one hundred eighty degrees proof (ninety per centum absolute alcohol) shall be deemed to have been removed for motive power, unless shown to the contrary.\n\"Whenever any of the oils mentioned above are, during the five years from June eighteen, nineteen hundred and fifty-two, used in agriculture and aviation, fifty per centum of the specific tax paid thereon shall be refunded by the Collector of Internal Revenue upon the submission of the following:\n\"(1) A sworn affidavit of the producer and two disinterested persons proving that the said oils were actually used in agriculture, or in lieu thereof.\n\"(2) Should the producer belong to any producers’ association or federation, duly registered with the Securities and Exchange Commission, the affidavit of the president of the association or federation, attesting to the fact that the oils were actually used in agriculture.\n\"(3) In the case of aviation oils, a sworn certificate satisfactory to the Collector proving that the said oils were actually used in aviation: Provided, That no such refunds shall be granted in respect to the oils used in aviation by citizens and corporations of foreign countries which do not grant equivalent refunds or exemptions in respect to similar oils used in aviation by citizens and corporations of the Philippines.\""}},{"id":"PH-H1269-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section one hundred and forty-five of the National Internal Revenue Code, as amended, is further amended to read as follows:\n\"Sec. 145. Specific Tax on Diesel fuel oil. — On fuel oil commercially known as diesel fuel oil, and on all similar fuel oils, having more or less the same generating power, there shall be collected, per metric ton, one peso.\""}},{"id":"PH-H1269-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The proceeds of the increased taxes accruing to the Highway Special Fund, as a result of the amendment of sections one hundred and forty-two and one hundred and forty-five of the National Internal Revenue Code as above provided, shall be set aside exclusively for amortizing loans or bonds that may have been authorized for the construction, reconstruction or improvement of highways including bridges as well as for liquidating toll bridges constructed from revolving funds authorized under Act Numbered Thirty-five hundred, as amended, whenever such liquidation is recommended by the Secretary of Public Works and Communications and approved by the President."}},{"id":"PH-H1269-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Municipal boards or councils may, notwithstanding the provisions of sections one hundred and forty-two and one hundred and forty-five of the National Internal Revenue Code, as hereinabove amended, levy an additional tax of not exceeding twenty-five per cent of the rates fixed in said sections, on manufactured oils sold or distributed within the limits of the city or municipality: Provided, That municipal taxes heretofore levied by cities through city ordinances on gasoline, airplane fuel, lubricating oil and other fuels, are hereby ratified and declared valid. The method of collecting said additional tax shall be prescribed by the municipal board or council concerned."}},{"id":"PH-H1269-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The proceeds of the additional tax on manufactured oils shall accrue to the road and bridge funds of the political subdivision for whose benefit the tax is collected: Provided, However, That whenever any oils mentioned above are used by miners or forest concessionaires in their operations, twenty-five per centum of the specific tax paid thereon shall be refunded by the Collector of Internal Revenue upon submission of proof of actual use of oils and under similar conditions enumerated in subparagraphs one and two of section one hereof, amending section one hundred forty-two of the Internal Revenue Code: Provided, further, That no new road shall be constructed unless the routes or location thereof shall have been approved by the Commissioner of Public Highways after a determination that such road can be made part of an integral and articulated route in the Philippine Highway System, as required in section twenty-six of the Philippine Highway Act of 1953."}},{"id":"PH-H1269-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1270"] = {"id":"PH-H1270","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1436_1956.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting the Province of Catanduanes Franchise for Electric Light, Heat and Power Systems in All Municipalities in the Province of Catanduanes","orig":"An Act Granting the Province of Catanduanes Franchise for Electric Light, Heat and Power Systems in All Municipalities in the Province of Catanduanes"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1436","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1436_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1270-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to the Province of Catanduanes, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain, and operate electric light, heat and power systems for the purpose of generating and distributing electric light, heat and/or power for sale in all the municipalities in the Province of Catanduanes."}},{"id":"PH-H1270-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1270-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The public interest so requiring, any act or municipal ordinance or resolution heretofore granting a franchise in favor of any individual or municipal corporation to construct, maintain and operate an electric light, heat and power system in any municipality in the Province of Catanduanes, is repealed."}},{"id":"PH-H1270-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon it approval.\nApproved: June 14, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1271"] = {"id":"PH-H1271","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1437_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Manila Boulevard in the City of Cavite to Rafael Palma Boulevard","orig":"An Act Changing the Name of Manila Boulevard in the City of Cavite to Rafael Palma Boulevard"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1437","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1437_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1271-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In recognition of the distinguished services to the country of Rafael Palma, first delegate of the Province of Cavite to the Philippine Assembly, the Manila Boulevard in the City of Cavite shall hereafter be known as Rafael Palma Boulevard."}},{"id":"PH-H1271-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1272"] = {"id":"PH-H1272","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1438_1956.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Seventy Thousand Pesos for the Yearly Expenses of the Philippine Representatives and Their Advisers to the International Labour Conference","orig":"An Act Appropriating the Sum of Seventy Thousand Pesos for the Yearly Expenses of the Philippine Representatives and Their Advisers to the International Labour Conference"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1438","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1438_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1272-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of seventy thousand pesos, or so much thereof as may be necessary, is hereby appropriated to cover the transportation, sundry and other expenses of the Philippine representatives and their advisers to the International Labour Conference, meetings and seminars of the International Labour Office and its committees. The per diems of the delegates or representatives shall not exceed fifty pesos and those of the advisers not more than forty pesos.\nThe aforesaid sum shall hereafter be included in the General Appropriation for the Department of Labor as long as the Philippines is a member of the International Labour Organization."}},{"id":"PH-H1272-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1273"] = {"id":"PH-H1273","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1439_1956.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting Leoncio Limpiado a Franchise for an Electric Light, Heat and Power System in the Municipality of Naval, Province of Leyte","orig":"An Act Granting Leoncio Limpiado a Franchise for an Electric Light, Heat and Power System in the Municipality of Naval, Province of Leyte"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1439","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1439_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1273-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Leoncio Limpiado, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the limits of the Municipality of Naval, Province of Leyte."}},{"id":"PH-H1273-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1273-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that, in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender his franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1273-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1274"] = {"id":"PH-H1274","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1440_1956.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting Messrs. Demetrio P. Correa and Guillermo Confesor a Franchise for an Electric Light, Heat and Power System in the Municipality of Cabatuan, Province of Iloilo","orig":"An Act Granting Messrs. Demetrio P. Correa and Guillermo Confesor a Franchise for an Electric Light, Heat and Power System in the Municipality of Cabatuan, Province of Iloilo"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1440","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1440_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1274-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Messrs. Demetrio P. Correa and Guillermo Confesor, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat, and/or power for sale within the Municipality of Cabatuan, Province of Iloilo."}},{"id":"PH-H1274-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantees shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H1274-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that, in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantees shall surrender their franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H1274-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p17"};
  FT["PH-H1275"] = {"id":"PH-H1275","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1956/ra_1441_1956.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Certain Provisions of Republic Act Numbered Three Hundred Twenty-One, Otherwise Known as the Charter of the City of Ozamis","orig":"An Act Amending Certain Provisions of Republic Act Numbered Three Hundred Twenty-One, Otherwise Known as the Charter of the City of Ozamis"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1441","issuingBody":"Congress of the Philippines","promulgatedDate":"1956-06-14","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1956/ra_1441_1956.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1275-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eight of Republic Act Numbered Three hundred twenty-one is amended to read as follows:\n\"Sec. 8. The Vice-Mayor. -There shall be elected by the qualified electors of the city, in conformity with the provisions of the Revised Election Code, a vice-mayor who shall receive a salary not exceeding three thousand six hundred pesos a year.\n\"In the event of sickness, absence, or other temporary incapacity of the Mayor, or in the event of a vacancy in the position of Mayor, the vice-mayor shall perform the duties of the Mayor. If, for any reason, the duties of the office of the Mayor cannot be performed by the vice-mayor, said duties shall be performed by the presiding officer of the Municipal Board. In case of incapacity of the officials mentioned above to perform the duties of the Mayor, the President shall appoint or designate one. The Acting Mayor shall have the same powers and duties as the Mayor, and if one appointed or designated is other than a government official he shall receive the same compensation.\""}},{"id":"PH-H1275-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first paragraph of section eleven of the same Act is amended to read as follows:\n\"Sec. 11. Constitution and organization of the Municipal Board: Compensation of members thereof. -The municipal Board shall be the legislative body of the city and shall be composed of eight councilors elected at large by popular vote during every election for provincial and municipal officials in conformity with the provisions of the Revised Election Code. The members of the Board shall elect on the first Monday of each year from among themselves a presiding officers who, during his incumbency, shall preside at all meetings of the Board in which he is present. In his absence, the Board shall elect one of its members as temporary presiding officer. In case of sickness, absence, suspension or other temporary disability of any member of the Board, or if necessary to maintain a quorum, the President of the Philippines may appoint a temporary substitute who shall possess all the rights and perform all the duties of a member of the Board until the return to duty of the regular incumbent.\""}},{"id":"PH-H1275-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Subsection (n) of section fifteen of the same Act is amended to read as follows:\n\"(n) To regulate, tax and fix the amount of the license fees on the business of: Hawkers, peddlers and hucksters, not including hucksters or peddlers who sell only native vegetables, fruits or foods, personally carried by the hucksters or peddlers; auctioneers, plumbers, barbers, collecting agencies, mercantile agencies, shipping and intelligence offices, private detective agencies, advertising agencies, beauty parlors, massagists, tatooers, jugglers, acrobats, hotels, clubs, restaurants, cafes, lodging houses, boarding houses, livery garages, livery stables, boarding stables, dealers in large cattle, public billiard tables, laundries, cleaning and dyeing establishments, public warehouses, circuses, and other similar parades, public vehicles, race tracks, horse races, bowling alleys, shooting galleries, slot machines, merry-go-rounds, pawnshops, dealers in second-hand merchandise, junk dealers, brewers, distillers, rectifiers, money changers, and brokers, public ferries, theaters, theatrical performances, cinematographs, public exhibitions and all other performances and places of amusement, and the keeping, preparation, and sale of meat, poultry, fish, game, butter, cheese, lard, vegetables, bread and other provisions.\""}},{"id":"PH-H1275-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The third paragraph of section forty-one of the same Act is amended to read as follows:\n\"At the option of the taxpayer, the tax for any year may be paid in two installments to be fixed annually by the Municipal Board simultaneously with the rate per centum of ad valorem taxation: Provided, That the time limit for the first and second installments shall be set at not later than the thirty-first day of May and the thirtieth day of November of each year, respectively.\""}},{"id":"PH-H1275-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The last paragraph of section seventy-six of the same Act is amended to read as follows:\n\"The Municipal Board may provide for such number of clerks in the office of the clerk of the municipal court as the needs of the service may demand.\""}},{"id":"PH-H1275-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section eighty-three of the same Act is amended to read as follows:\n\"Sec. 83. The City Auditor. -The City Auditor shall, under the supervision of the Auditor General, receive and audit all accounts of the city, in accordance with the provisions of law relating to government accounts and accounting. The city auditor shall be appointed by the Auditor General and shall receive the same salary as the city treasurer, one-half of which shall be paid by the city government and the other half by the National Government: Provided, However , That the city shall pay the whole salary of the said city auditor until the share of the National Government is provided for by Congress.\""}},{"id":"PH-H1275-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1956."}}],"pack":"ph-p17"};
})(typeof window !== 'undefined' ? window : globalThis);
